window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-13"] = [
  {id:"cn--1978--p01",track:"cn",year:1978,yearApprox:false,dim:"politics",weight:4,title:"真理标准问题讨论在全国展开",summary:"1978年5月11日《光明日报》发表《实践是检验真理的唯一标准》。",detail:{background:"1977年“两个凡是”方针提出后，中央党校部分教员与南京大学教师胡福明分别围绕检验真理的标准撰写文章，《光明日报》编辑部与《理论动态》编辑部共同修改定稿。",process:"1978年5月10日，中央党校内部刊物《理论动态》第60期刊发《实践是检验真理的唯一标准》；5月11日《光明日报》以“本报特约评论员”名义发表同一文章，5月12日《人民日报》《解放军报》及多家地方报纸转载。文章提出检验真理的标准只能是社会实践，理论要与实践的统一是马克思主义的一个基本原则。",impact:"据1981年《关于建国以来党的若干历史问题的决议》的表述，这场讨论“对于促进全党同志和全国人民解放思想，端正思想路线，具有深远的历史意义”；1978年12月13日邓小平在中央工作会议闭幕会上作《解放思想，实事求是，团结一致向前看》讲话，为十一届三中全会作了准备。",figures:["胡福明","杨西光","孙长江","邓小平"],place:"北京、南京",state:"中华人民共和国",sources:["《光明日报》1978年5月11日、《理论动态》第60期（1978年5月10日）","《三中全会以来重要文献选编》（人民出版社1982年）"],"tags":["真理标准讨论","实事求是","思想路线"]},related:["cn--1977--p02", "cn--1978--p02"]},
  {id:"cn--1978--p02",track:"cn",year:1978,yearApprox:false,dim:"politics",weight:5,title:"中共十一届三中全会",summary:"1978年12月18日至22日全会决定把工作重点转到现代化建设上。",detail:{background:"1978年11月10日至12月15日中央工作会议先行召开，与会者就平反历史冤案、农业方针与思想路线问题充分发言，邓小平在闭幕会上作《解放思想，实事求是，团结一致向前看》讲话，为全会定下基调。",process:"1978年12月18日至22日，中国共产党第十一届中央委员会第三次全体会议在北京举行，出席会议的中央委员164人、候补中央委员112人；全会增选陈云为中央委员会副主席，邓颖超、胡耀邦、王震为中央政治局委员，选举产生中央纪律检查委员会（陈云任第一书记）；全会决定从1979年1月起把全党工作重点转移到社会主义现代化建设上来，停止使用“以阶级斗争为纲”的口号，并原则通过了《1979年、1980年国民经济计划安排》和《中共中央关于加快农业发展若干问题的决定（草案）》。",impact:"全会重新确立解放思想、实事求是的路线，形成以邓小平为核心的中央领导集体，启动农业责任制、政企关系与对外经济领域的政策调整；据《中国共产党历史》第二卷的表述，这次会议是“建国以来我党历史上具有深远意义的伟大转折”。",figures:["邓小平","陈云","胡耀邦","叶剑英","李先念"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十一届中央委员会第三次全体会议公报》（1978年12月22日）、《三中全会以来重要文献选编》（人民出版社1982年）"],"tags":["十一届三中全会","工作重点转移","改革开放"]},related:["cn--1978--p01", "cn--1978--e01", "cn--1979--e01", "world--1978--p03"]},
  {id:"cn--1978--p03",track:"cn",year:1978,yearApprox:false,dim:"politics",weight:3,title:"中日和平友好条约生效",summary:"1978年8月12日条约在北京签署，10月23日邓小平访日互换批准书。",detail:{background:"1972年9月中日发表联合声明实现邦交正常化；此后因“反霸权”条款等分歧，缔结和平友好条约的谈判几度中断，1978年7月重启后迅速达成协议。",process:"1978年8月12日，中国外交部长黄华与日本国外相园田直在北京签署《中日和平友好条约》，条约确认《中日联合声明》所表述的各项原则，规定双方应在和平共处五项原则基础上发展持久的和平友好关系，并在相互关系中都不谋求霸权；1978年10月22日至29日邓小平访问日本，10月23日双方在东京互换批准书，条约正式生效。",impact:"据新华社报道与外交部编年资料，条约与两个政治文件共同构成两国关系的法律基础；1979年12月大平正芳访华后日本开始对华提供日元贷款，1980年代日本对华政府贷款与两国人员往来明显扩大。",figures:["邓小平","黄华","园田直"],place:"北京（签署）、东京（互换批准书）",state:"中华人民共和国",sources:["《中日和平友好条约》（1978年8月12日签订）、中华人民共和国外交部编《外交大事记》"],"tags":["中日和平友好条约","不谋霸权","中日关系"]},related:["cn--1972--p01", "cn--1979--p01", "world--1978--p04", "world--1978--f01"]},
  {id:"cn--1978--i01",track:"cn",year:1978,yearApprox:false,dim:"institution",weight:3,title:"1978年宪法公布施行",summary:"1978年3月5日五届全国人大一次会议通过宪法，共4章60条。",detail:{background:"1954年宪法之后，1975年宪法条文简略并带有浓厚政治运动色彩；“文化大革命”结束后需要重建国家机构的法制基础，但制宪工作仍受“继续革命”论影响。",process:"1978年3月1日至5日，第五届全国人民代表大会第一次会议在北京举行，会议通过《中华人民共和国宪法》，共4章60条，恢复和补充了国家机构、公民基本权利义务的规定，同时保留“无产阶级专政下继续革命”等表述，并写明公民有运用“大鸣、大放、大辩论、大字报”的权利；会议选举叶剑英为全国人大常委会委员长，决定华国锋任国务院总理。",impact:"1980年9月10日五届全国人大三次会议通过决议，取消宪法中关于“四大”的规定；1982年12月4日五届全国人大五次会议通过现行宪法，对1978年宪法作出全面修改，这部宪法的过渡性质由此结束。",figures:["叶剑英","华国锋"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法》（1978年3月5日第五届全国人民代表大会第一次会议通过）、第五届全国人民代表大会第一次会议公报"],"tags":["1978年宪法","国家机构","四大"]},related:["cn--1954--i01", "cn--1978--i02", "world--1982--p02"]},
  {id:"cn--1978--i02",track:"cn",year:1978,yearApprox:false,dim:"institution",weight:2,title:"人大常委会决定义务兵与志愿兵结合",summary:"1978年3月7日通过《关于兵役制问题的决定》，部分义务兵改为志愿兵。",detail:{background:"1955年《中华人民共和国兵役法》确立义务兵役制；部队技术装备在1970年代逐步复杂化，短期服役的义务兵难以保留专业技术骨干。",process:"1978年3月7日，第五届全国人民代表大会常务委员会第一次会议通过《关于兵役制问题的决定》，规定现役义务兵服现役期满，根据军队需要和本人自愿，可以改为志愿兵，人民解放军由此实行以义务兵为主体的义务兵与志愿兵相结合的兵役制度。",impact:"据《中国人民解放军军史》的说明，这一决定缓解了技术骨干流失问题；1984年5月31日六届全国人大二次会议通过新的《中华人民共和国兵役法》，1998年12月修改后形成以志愿兵役为主体的兵役制度。",figures:["徐向前"],place:"北京",state:"中华人民共和国",sources:["全国人民代表大会常务委员会《关于兵役制问题的决定》（1978年3月7日）、《中华人民共和国兵役法》（1984年）"],"tags":["兵役制度","义务兵","志愿兵"]},related:["cn--1978--i01"]},
  {id:"cn--1978--e01",track:"cn",year:1978,yearApprox:false,dim:"economy",weight:5,title:"安徽凤阳小岗村实行“大包干”",summary:"1978年11月24日小岗生产队18户农民签字约定分田到户。",detail:{background:"1970年代末，安徽、甘肃、贵州等地部分生产队已自发实行包产到组或包产到户；1978年夏秋安徽出现严重旱灾，秋种时许多生产队缺乏统一经营的条件。",process:"1978年11月24日夜，安徽省凤阳县梨园公社小岗生产队18户农民在一份约定上签字按手印，决定把土地分户经营、自负盈亏，并写明若因包产到户出事，干部责任由全队社员承担；1979年夏收，小岗生产队粮食总产约13.3万斤，为数年来最高，当年安徽全省实行包产、包干到户的生产队比重明显上升。",impact:"1980年9月中共中央印发《关于进一步加强和完善农业生产责任制的几个问题》（中发〔1980〕75号），承认贫困地区包产到户的社会主义性质；1982年1月中央一号文件《全国农村工作会议纪要》进一步确认包产到户、包干到户属于集体经济的生产责任制，家庭联产承包责任制随后在全国推开。",figures:["严宏昌","严金昌"],place:"安徽凤阳小岗村",state:"中华人民共和国",sources:["《凤阳县志》（方志出版社1992年）、中共中央《关于进一步加强和完善农业生产责任制的几个问题》（中发〔1980〕75号）"],"tags":["大包干","家庭联产承包","农村改革"]},related:["cn--1978--p02", "cn--1980--e02", "cn--1982--e01"]},
  {id:"cn--1978--s01",track:"cn",year:1978,yearApprox:false,dim:"science",weight:4,title:"全国科学大会召开",summary:"1978年3月18日至31日大会在北京举行，提出“科学技术是生产力”。",detail:{background:"1975年邓小平主持整顿时曾提出“科学技术也是生产力”；“文化大革命”结束后科研秩序混乱，1977年9月中央重新成立国家科学技术委员会，方毅任主任。",process:"1978年3月18日至31日，全国科学大会在北京召开，与会代表近4000人；邓小平在讲话中阐明“科学技术是生产力”、知识分子的绝大多数“已经是工人阶级自己的一部分”，华国锋作《提高整个中华民族的科学文化水平》报告，大会制定《1978年到1985年全国科学技术发展规划纲要（草案）》，提出8个领域27个方面的重点科研任务，并表彰一批科研成果。",impact:"据大会文件与《当代中国的科学事业》的记载，这次会议被视为“科学的春天”的起点，郭沫若在大会上发表书面讲话《科学的春天》；会后恢复职称评定、重建科研秩序，1978年至1985年规划带动国家重点实验室与科技攻关计划先后建立。",figures:["邓小平","方毅","郭沫若","华国锋"],place:"北京",state:"中华人民共和国",sources:["《1978年到1985年全国科学技术发展规划纲要（草案）》、《人民日报》1978年3月31日"],"tags":["全国科学大会","科学技术是生产力","发展规划"]},related:["cn--1977--i01", "cn--1978--p02"]},
  {id:"cn--1978--c01",track:"cn",year:1978,yearApprox:false,dim:"culture",weight:2,title:"话剧《于无声处》首演",summary:"1978年6月宗福先创作的四幕话剧在上海业余会演中搬上舞台。",detail:{background:"1976年清明前后出现悼念周恩来、批评“四人帮”的群众活动，1978年11月中共北京市委宣布该事件为革命行动；同一题材在“文化大革命”后首先由业余作者搬上舞台。",process:"1978年6月，上海工人、教师宗福先创作的四幕话剧《于无声处》在上海工业系统业余文艺会演中首次演出，剧情围绕1976年清明事件及其后的家庭冲突展开；同年剧本由《文汇报》《戏剧报》发表，1978年底至1979年北京、天津等地专业院团相继演出，中央人民广播电台播放了演出录音。",impact:"据《中国话剧艺术史》与当年报刊的记述，《于无声处》是“文化大革命”后第一部产生全国性影响的现实题材话剧，其演出与真理标准讨论相互呼应，也带动了一批反思题材的戏剧与报告文学创作。",figures:["宗福先"],place:"上海",state:"中华人民共和国",sources:["《文汇报》1978年刊登《于无声处》剧本、《戏剧报》1978年第7期"],"tags":["于无声处","反思题材","业余创作"]},related:["cn--1976--p02", "cn--1978--p01"]},
  {id:"cn--1979--p01",track:"cn",year:1979,yearApprox:false,dim:"politics",weight:5,title:"中美正式建交与邓小平访美",summary:"1979年1月1日中美建交，1月29日邓小平开始对美国的国事访问。",detail:{background:"1978年12月15日，中美双方同时发表《关于建立外交关系的联合公报》；这一谈判与十一届三中全会的对外开放决策同期完成，美国方面由总统卡特宣布。",process:"1979年1月1日，中美两国正式建立外交关系，美国承认中华人民共和国政府是中国的唯一合法政府，并承认中国的立场，即只有一个中国、台湾是中国的一部分；美方宣布终止美台《共同防御条约》，并在一年内从台湾撤出军队和军事装备。1979年1月29日至2月5日，邓小平应卡特邀请对美国进行国事访问，是中华人民共和国成立后中国领导人首次访美。",impact:"据新华社报道与两国政府公布的文件，建交后中美在科技、文化、经贸领域陆续签署协定，1979年1月31日签订《中美科技合作协定》；两国关系此后因对台军售等问题出现摩擦，1982年8月17日发表关于美国对台军售问题的第三个联合公报。",figures:["邓小平","卡特"],place:"北京、华盛顿",state:"中华人民共和国",sources:["《中华人民共和国和美利坚合众国关于建立外交关系的联合公报》（1978年12月16日双方同时发表）、《人民日报》1979年2月6日"],"tags":["中美建交","邓小平访美","一个中国"]},related:["cn--1978--p03", "cn--1979--m01", "cn--1982--p02"]},
  {id:"cn--1979--p02",track:"cn",year:1979,yearApprox:false,dim:"politics",weight:3,title:"全国人大常委会发表《告台湾同胞书》",summary:"1979年1月1日提出和平统一方针，同日宣布停止对金门等岛炮击。",detail:{background:"1949年后两岸长期隔绝并维持军事对峙；1978年12月十一届三中全会后，对台工作的方针开始调整，中美建交同日发表的文件亦涉及台湾问题。",process:"1979年1月1日，全国人民代表大会常务委员会发表《告台湾同胞书》，提出在解决统一问题时尊重台湾现状和台湾各界人士的意见，建议双方尽快实现通邮、通航，发展贸易、互通有无并进行经济交流；同日，国防部长徐向前发表声明，宣布自当日起停止对大金门、小金门、大担、二担等岛屿的炮击。",impact:"据《中国共产党历史》第二卷的叙述，这一文件标志对台政策由“解放台湾”的提法转向和平统一方向；1981年9月30日叶剑英提出关于台湾回归的九条方针政策，1982年12月现行宪法第31条规定国家在必要时得设立特别行政区，为“一国两制”提供宪法依据。",figures:["叶剑英","徐向前"],place:"北京",state:"中华人民共和国",sources:["全国人大常委会《告台湾同胞书》（1979年1月1日）、国防部长徐向前关于停止炮击金门等岛屿的声明（1979年1月1日）"],"tags":["告台湾同胞书","和平统一","停止炮击"]},related:["cn--1979--p01", "cn--1981--p02", "cn--1982--i01"]},
  {id:"cn--1979--p03",track:"cn",year:1979,yearApprox:false,dim:"politics",weight:3,title:"邓小平提出坚持四项基本原则",summary:"1979年3月30日在党的理论工作务虚会上作《坚持四项基本原则》讲话。",detail:{background:"1978年底至1979年初，思想解放的同时，社会上也出现涉及社会主义制度与中国共产党的领导地位的多种议论；中共中央召开理论工作务虚会以讨论思想理论问题。",process:"1979年3月30日，邓小平在党的理论工作务虚会上作《坚持四项基本原则》的讲话，提出必须在思想政治上坚持社会主义道路、坚持无产阶级专政即人民民主专政、坚持共产党的领导、坚持马列主义毛泽东思想，并说明解放思想与四项基本原则并不互相排斥；4月起中央就这一讲话向党内外传达。",impact:"据《邓小平文选》第二卷的编注说明，这篇讲话为当时的思想解放运动划定了界限；1987年10月中共十三大把“一个中心、两个基本点”写入党在社会主义初级阶段的基本路线，四项基本原则与改革开放并列其中。",figures:["邓小平"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第二卷收录《坚持四项基本原则》（1979年3月30日）、《人民日报》1979年4月1日"],"tags":["理论工作务虚会","四项基本原则","基本路线"]},related:["cn--1978--p01", "cn--1987--p01"]},
  {id:"cn--1979--i01",track:"cn",year:1979,yearApprox:false,dim:"institution",weight:4,title:"五届全国人大二次会议一次通过七部法律",summary:"1979年7月1日通过刑法、刑事诉讼法与中外合资经营企业法等。",detail:{background:"“文化大革命”期间法制遭到严重破坏，1978年宪法仍保留部分“左”的条文；五届全国人大二次会议集中立法，以重建国家机构与司法活动的依据。",process:"1979年6月18日至7月1日，第五届全国人民代表大会第二次会议在北京举行，通过《中华人民共和国刑法》《中华人民共和国刑事诉讼法》《人民法院组织法》《人民检察院组织法》，以及重新修订的《选举法》和《地方各级人民代表大会和地方各级人民政府组织法》，并通过《中华人民共和国中外合资经营企业法》；修改后的选举法把县级人民代表大会代表改为由选民直接选举，并规定县级以上地方各级人大设立常务委员会。",impact:"据全国人大常委会法制工作委员会的说明，这七部法律在新中国法制恢复过程中具有奠基作用；《刑法》自1980年1月1日起施行，当时规定了类推制度，1997年修订刑法时改采罪刑法定原则。",figures:["彭真","叶剑英"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国刑法》（1979年7月1日通过、1980年1月1日施行）、《中华人民共和国中外合资经营企业法》（1979年7月1日通过）、第五届全国人民代表大会第二次会议公报"],"tags":["七部法律","县级直接选举","中外合资经营企业法"]},related:["cn--1978--i01", "cn--1979--e01"]},
  {id:"cn--1979--e01",track:"cn",year:1979,yearApprox:false,dim:"economy",weight:4,title:"中央批准广东福建实行特殊政策",summary:"1979年7月15日中央批转两省报告，同意试办“出口特区”。",detail:{background:"1978年广东边境外流人员增多，利用侨资与外资发展出口加工的设想由广东省委提出；1979年初，中央有关部门研究后同意两省在对外经济活动中先走一步。",process:"1979年4月中央工作会议期间，广东省委负责人提出办出口加工区的建议；1979年7月15日，中共中央、国务院批转《广东省委、福建省委关于对外经济活动实行特殊政策和灵活措施的两个报告》（中发〔1979〕50号），同意两省在外贸、引进外资等方面实行特殊政策、灵活措施，并在深圳、珠海、汕头和厦门试办出口特区；1980年3月“出口特区”改称“经济特区”。",impact:"这份文件是改革开放初期区域政策试验的起点：1980年8月《广东省经济特区条例》经全国人大常委会批准，深圳、珠海、汕头经济特区正式设立，厦门经济特区同年10月设立；1984年2月邓小平视察深圳、珠海、厦门并为此题词。",figures:["邓小平","习仲勋","谷牧"],place:"北京、广东深圳、福建厦门",state:"中华人民共和国",sources:["中共中央、国务院批转广东、福建两省报告的通知（中发〔1979〕50号，1979年7月15日）、《邓小平文选》第二卷"],"tags":["特殊政策","出口特区","中发1979年50号"]},related:["cn--1978--p02", "cn--1980--e03", "world--1980--e01"]},
  {id:"cn--1979--c01",track:"cn",year:1979,yearApprox:false,dim:"culture",weight:3,title:"中国文学艺术工作者第四次代表大会",summary:"1979年10月30日至11月16日大会召开，邓小平致祝辞。",detail:{background:"1960年第三次全国文代会后，文艺界历经多次批判运动，组织与刊物长期停摆；“文化大革命”结束后作家、艺术家要求恢复创作活动与团体生活。",process:"1979年10月30日至11月16日，中国文学艺术工作者第四次代表大会在北京召开，文学、戏剧、电影、美术、音乐等各界代表与会；10月30日邓小平代表中共中央、国务院致祝辞，提出党对文艺工作的领导要根据文学艺术的特征和发展规律来进行，不要求文学艺术从属于临时的、具体的、直接的政治任务。",impact:"据大会文件与随后《人民日报》的报道，这次会议恢复了文学艺术界联合会的组织活动；1980年起文艺工作的口号由“文艺为政治服务”调整为“为人民服务、为社会主义服务”，此后几年出现反思文学、改革文学与朦胧诗的创作风貌。",figures:["邓小平","巴金"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第二卷《在中国文学艺术工作者第四次代表大会上的祝词》（1979年10月30日）、《人民日报》1979年10月31日"],"tags":["第四次文代会","二为方向","文艺政策"]},related:["cn--1977--c01", "cn--1978--p01"]},
  {id:"cn--1979--m01",track:"cn",year:1979,yearApprox:false,dim:"military",weight:4,title:"对越自卫反击作战",summary:"1979年2月17日至3月16日广西、云南边防部队进行自卫还击作战。",detail:{background:"1975年越南统一后，中越在柬埔寨问题、陆地边界争端与华侨问题上矛盾激化；1978年12月越南出兵柬埔寨，1979年2月边界武装冲突增多。",process:"1979年2月17日，中国广西、云南边防部队发起自卫还击作战，分别向谅山、老街方向进攻，东线由许世友指挥、西线由杨得志指挥；3月5日中国政府宣布作战达到预期目的并开始撤军，3月16日边防部队全部撤回境内。此后中越陆地边界冲突持续，老山、者阴山地区的轮战延续到1989年。",impact:"据新华社1979年的报道与《中国人民解放军军史》的记述，此役使中越进入长达十年的军事对峙；两国关系正常化为1991年11月，陆地边界条约于1999年12月30日签署，2008年完成勘界立碑。",figures:["许世友","杨得志"],place:"广西、云南边境及越南谅山、老街地区",state:"中华人民共和国",sources:["新华社1979年3月5日报道、《中国人民解放军军史》（军事科学出版社2010年）"],"tags":["对越自卫反击","中越关系","边境作战"]},related:["cn--1979--p01", "cn--1991--p01", "world--1979--m04"]},
  {id:"cn--1980--i01",track:"cn",year:1980,yearApprox:false,dim:"institution",weight:3,title:"十一届五中全会恢复中央书记处",summary:"1980年2月23日至29日全会通过《关于党内政治生活的若干准则》。",detail:{background:"1979年底中央着手复查“文化大革命”遗留的重大案件，并研究如何从制度上防止个人专断；胡耀邦主持起草党内政治生活准则。",process:"1980年2月23日至29日，中国共产党第十一届中央委员会第五次全体会议在北京举行，通过《关于党内政治生活的若干准则》；全会决定重新设立中共中央书记处，选举胡耀邦为中央委员会总书记；全会通过《关于为刘少奇同志平反的决议》，并决定提前召开中国共产党第十二次全国代表大会。",impact:"据《关于党内政治生活的若干准则》单行本前言的说明，准则的制定与书记处的恢复是改革开放后党内制度重建的起点；1980年8月中央政治局扩大会议进一步提出领导制度改革，1982年十二大通过新党章。",figures:["胡耀邦","邓小平","陈云"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十一届中央委员会第五次全体会议公报》（1980年2月29日）、《关于党内政治生活的若干准则》（人民出版社1980年）"],"tags":["十一届五中全会","中央书记处","党内政治生活准则"]},related:["cn--1980--p01", "cn--1980--i02"]},
  {id:"cn--1980--p01",track:"cn",year:1980,yearApprox:false,dim:"politics",weight:4,title:"中共中央为刘少奇平反",summary:"1980年2月29日五中全会通过平反决议，5月17日举行追悼大会。",detail:{background:"1968年10月八届十二中全会通过《关于叛徒、内奸、工贼刘少奇罪行的审查报告》，决定把刘少奇“永远开除出党”；刘少奇于1969年11月12日在开封病逝。1978年12月十一届三中全会后，中央纪律检查委员会与中央组织部对案件进行复查。",process:"1980年2月29日，中共十一届五中全会通过《关于为刘少奇同志平反的决议》，撤销八届十二中全会强加给刘少奇的罪名和“永远开除出党”的决议，恢复其作为马克思主义者和无产阶级革命家、党和国家主要领导人之一的名誉；1980年5月17日，刘少奇追悼大会在北京人民大会堂举行，邓小平致悼词。",impact:"据1981年《关于建国以来党的若干历史问题的决议》的表述，为刘少奇平反带动了“文化大革命”以来一系列冤假错案的复查工作；据中共中央组织部1982年公布的信息，到1982年底全国已为大量受处理的干部复查平反，具体口径与统计数字由各地分别汇总。",figures:["刘少奇","邓小平","王光美"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十一届中央委员会第五次全体会议关于为刘少奇同志平反的决议》（1980年2月29日）、新华社1980年5月17日关于追悼大会的报道"],"tags":["刘少奇平反","冤假错案","五中全会"]},related:["cn--1968--p01", "cn--1980--i01", "cn--1981--p01"]},
  {id:"cn--1980--i02",track:"cn",year:1980,yearApprox:false,dim:"institution",weight:4,title:"邓小平论党和国家领导制度的改革",summary:"1980年8月18日中央政治局扩大会议讲话提出改革领导制度。",detail:{background:"1977年至1980年，权力过分集中、干部领导职务实际上的终身制与机构臃肿等问题被多次提出；十一届五中全会后中央着手研究领导制度的改革方案。",process:"1980年8月18日至23日，中央政治局召开扩大会议，邓小平作《党和国家领导制度的改革》的讲话，指出领导制度、组织制度问题更带有根本性、全局性、稳定性和长期性，提出废除干部领导职务实际存在的终身制、改变党政不分与以党代政、精简机构并加强法制；会议决定把这个草案交各省、市、自治区党委和中央党内外一定范围讨论修改后，提交十一届六中全会审议。",impact:"据《邓小平文选》第二卷的编注，这篇讲话被视为此后政治体制改革的纲领性文件；1982年现行宪法对国家主席、国务院总理等领导职务规定连续任职不得超过两届，1982年国务院机构改革与干部队伍“四化”方针均与此讲话的方向衔接。",figures:["邓小平","陈云","叶剑英"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第二卷收录《党和国家领导制度的改革》（1980年8月18日）、《三中全会以来重要文献选编》（人民出版社1982年）"],"tags":["领导制度改革","终身制","政治体制改革"]},related:["cn--1980--i01", "cn--1982--i01"]},
  {id:"cn--1980--i03",track:"cn",year:1980,yearApprox:false,dim:"institution",weight:2,title:"新中国第一部个人所得税法通过",summary:"1980年9月10日五届全国人大三次会议通过《个人所得税法》。",detail:{background:"1979年《中外合资经营企业法》通过后，外籍与港澳台人员在华取得的收入增多，需要相应的税收法律依据；此前中国对国内居民个人不征所得税。",process:"1980年9月10日，第五届全国人民代表大会第三次会议通过《中华人民共和国个人所得税法》，自公布之日起施行，就在中国境内居住满规定期限的外籍人员等的工资、薪金等所得规定超额累进税率与比例税率，并明确免税项目与申报办法。",impact:"据国家税务总局的税法沿革资料，这部税法当时只适用于外籍人员；1986年国务院分别发布《城乡个体工商业户所得税暂行条例》和《个人收入调节税暂行条例》，1993年10月修订为统一的《个人所得税法》自1994年施行，2018年再次修订，实行综合与分类相结合的税制。",figures:["叶剑英"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国个人所得税法》（1980年9月10日第五届全国人民代表大会第三次会议通过）、《中华人民共和国税收法规汇编》"],"tags":["个人所得税","涉外税收","1980年"]},related:["cn--1979--i01", "cn--1979--e01"]},
  {id:"cn--1980--i04",track:"cn",year:1980,yearApprox:false,dim:"institution",weight:3,title:"《中华人民共和国学位条例》通过",summary:"1980年2月12日人大常委会通过学位条例，1981年1月1日施行。",detail:{background:"1949年后中国长期未实行学位制度，“文化大革命”期间研究生培养中断；1977年恢复研究生招生后，需要为学位授予与质量评价提供法律依据。",process:"1980年2月12日，第五届全国人民代表大会常务委员会第十三次会议通过《中华人民共和国学位条例》，自1981年1月1日起施行，规定学士、硕士、博士三级学位的授予条件、学科门类与审批程序，并规定国务院设立学位委员会；1981年5月国务院批准成立国务院学位委员会，随后公布首批博士、硕士学位授予单位和授予学科、专业名单。",impact:"据教育部《中国教育年鉴》的记述，学位条例是新中国第一部教育法律，其施行使研究生教育与学位授予进入制度化轨道；1986年3月六届全国人大四次会议通过《中华人民共和国义务教育法》，1995年《中华人民共和国教育法》进一步确立教育基本法律制度。",figures:["方毅"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国学位条例》（1980年2月12日通过、1981年1月1日施行）、第五届全国人民代表大会常务委员会第十三次会议公报"],"tags":["学位条例","研究生教育","教育立法"]},related:["cn--1977--i02", "cn--1977--i01"]},
  {id:"cn--1980--e01",track:"cn",year:1980,yearApprox:false,dim:"economy",weight:2,title:"温州核发第一张个体工商业营业执照",summary:"1980年12月11日温州工商所向商贩章华妹核发营业执照。",detail:{background:"1979年前后全国约有2000万城镇青年需要安排就业，个体经营在温州、大连等地重新出现；1980年8月中央提出“三结合”就业方针，为个体经济留出政策空间。",process:"1980年8月17日至21日，中共中央召开全国劳动就业工作会议，提出在国家统筹规划和指导下，实行劳动部门介绍就业、自愿组织起来就业和自谋职业相结合的方针；1980年12月11日，温州市工商行政管理局（鼓楼工商所）向女装商贩章华妹核发编号10101号的个体工商业营业执照，被当地档案部门作为改革开放后全国第一张个体工商业营业执照保存。",impact:"据《中国工商行政管理年鉴》与国务院发展研究中心的资料，1978年底全国个体经营者约15万人，1981年国务院发布《关于城镇非农业个体经济若干政策性规定》后户数迅速增加，个体与私营经济此后成为就业的重要渠道。",figures:["章华妹"],place:"浙江温州",state:"中华人民共和国",sources:["中共中央转发《进一步做好城镇劳动就业工作》的文件（1980年8月）、温州市工商行政管理局档案（1980年12月11日核发的营业执照）"],"tags":["个体经济","待业安置","营业执照"]},related:["cn--1980--e02", "cn--1979--p03"]},
  {id:"cn--1980--e02",track:"cn",year:1980,yearApprox:false,dim:"economy",weight:3,title:"中央75号文件承认包产到户",summary:"1980年9月25日中央印发《关于进一步加强和完善农业生产责任制的几个问题》。",detail:{background:"1979年9月十一届四中全会通过《中共中央关于加快农业发展若干问题的决定》，但当时文件仍限定包产到户的适用范围；1980年春夏，安徽、贵州、内蒙古等地实行承包的生产队增加，中央内部意见分歧明显。",process:"1980年9月14日至22日，中共中央召开各省、市、自治区党委第一书记座谈会，会议意见整理为《关于进一步加强和完善农业生产责任制的几个问题》，9月25日由中共中央印发（中发〔1980〕75号）；文件规定在边远山区和贫困落后地区，群众要求包产到户的应当支持，可以包产到户，也可以包干到户，并明确在生产队领导下这是依附于社会主义经济的合作经济形式。",impact:"据《新编中华人民共和国常用法律法规汇编》与农业部门统计资料，文件下发后承包形式由贫困地区向全国扩展，到1982年上半年全国实行包产到户、包干到户的生产队已占生产队总数的九成以上；1981年邓小平在同中央负责人谈话中进一步肯定农村政策变化的效果。",figures:["邓小平","万里","胡耀邦"],place:"北京",state:"中华人民共和国",sources:["中共中央《关于进一步加强和完善农业生产责任制的几个问题》（中发〔1980〕75号，1980年9月25日印发）、《邓小平文选》第二卷《关于农村政策问题》（1980年5月31日）"],"tags":["75号文件","包产到户","农业生产责任制"]},related:["cn--1978--e01", "cn--1982--e01"]},
  {id:"cn--1980--e03",track:"cn",year:1980,yearApprox:false,dim:"economy",weight:4,title:"《广东省经济特区条例》获批准",summary:"1980年8月26日全国人大常委会批准条例，深圳等经济特区设立。",detail:{background:"1979年7月中央批准广东、福建两省实行特殊政策后，特区还缺少法律地位、关税与土地、劳动等制度的统一依据。",process:"1980年8月26日，第五届全国人民代表大会常务委员会第十五次会议批准《广东省经济特区条例》，决定在广东省的深圳、珠海、汕头三市分别划出区域设置经济特区（其中深圳经济特区规划面积327.5平方公里），实行独立的经济管理体制和特殊的经济政策，对投资者给予税收优惠，企业所得税按15%的税率征收；同年10月国务院批准设立厦门经济特区。",impact:"据深圳市统计局与《深圳经济特区发展史》的资料，1980年设区之初深圳以出口加工与基建起步，1990年全市国内生产总值达171.67亿元；特区经验推动了1984年进一步开放14个沿海港口城市的决策。",figures:["习仲勋","谷牧","任仲夷"],place:"广东深圳、珠海、汕头",state:"中华人民共和国",sources:["全国人民代表大会常务委员会关于批准《广东省经济特区条例》的决议（1980年8月26日）、《广东省经济特区条例》"],"tags":["经济特区","广东省经济特区条例","税收优惠"]},related:["cn--1979--e01", "cn--1984--e01", "world--1980--e01"]},
  {id:"cn--1980--m01",track:"cn",year:1980,yearApprox:false,dim:"military",weight:4,title:"中国首次洲际火箭全程飞行试验",summary:"1980年5月18日向太平洋预定海域发射运载火箭，5月9日国务院公告。",detail:{background:"1970年代中国在本国陆地范围内无法进行全射程试验，远洋测量与落区观测能力不足；1977年起中央批准建设远洋测量船队并在南太平洋设置着陆观测点。",process:"1980年5月9日，中华人民共和国国务院发布公告，宣布1980年5月12日至6月30日中国向太平洋预定海域发射一枚运载火箭，并请有关国家的飞机、船舶避开公布的水域；1980年5月18日火箭发射，弹头落入南太平洋预定海域，全程飞行试验成功，新华社于5月19日向国内外播发消息。",impact:"据《当代中国的国防科技事业》的记述，这次试验检验了远程火箭的制导精度与再入防热等关键技术，使中国成为具备洲际火箭全射程试验能力的国家之一；1984年10月1日国庆35周年阅兵式上，“东风五号”战略导弹首次公开展出。",figures:["张爱萍","宋健"],place:"中国西北导弹试验场发射，落区为南太平洋预定海域",state:"中华人民共和国",sources:["《中华人民共和国国务院公告》（1980年5月9日）、新华社1980年5月19日报道","《当代中国的国防科技事业》（当代中国出版社1992年）"],"tags":["洲际火箭","全程飞行试验","太平洋落区"]},related:["cn--1970--s01", "cn--1984--m01"]},
  {id:"cn--1981--p01",track:"cn",year:1981,yearApprox:false,dim:"politics",weight:4,title:"十一届六中全会通过历史决议",summary:"1981年6月27日至29日全会通过《关于建国以来党的若干历史问题的决议》。",detail:{background:"1979年至1981年党内围绕如何评价毛泽东与“文化大革命”长期讨论；1980年3月成立决议起草领导小组，1981年春夏先后组织党内4000多名干部和部分党外人士讨论草稿。",process:"1981年6月27日至29日，中国共产党第十一届中央委员会第六次全体会议在北京举行，通过《关于建国以来党的若干历史问题的决议》；决议分7个部分，对1949年以来重大历史事件特别是“文化大革命”作出总结，指出毛泽东的功绩是第一位的、错误是第二位的，并把毛泽东晚年的错误同毛泽东思想区分开来；全会同意华国锋辞去中央委员会主席、中央军委主席职务的请求，选举胡耀邦为中央委员会主席，邓小平为中央军事委员会副主席。",impact:"据决议文本与1981年7月1日《人民日报》社论，这一决议统一了党内对“文化大革命”和毛泽东功过的评价，成为此后官方叙述的基本依据；决议对1978年以来路线的确认，也为1982年中共十二大提出“建设有中国特色的社会主义”提供了政治前提。",figures:["邓小平","胡耀邦","华国锋","胡乔木"],place:"北京",state:"中华人民共和国",sources:["《关于建国以来党的若干历史问题的决议》（人民出版社1981年）、《中国共产党第十一届中央委员会第六次全体会议公报》（1981年6月29日）"],"tags":["历史决议","十一届六中全会","毛泽东评价"]},related:["cn--1978--p01", "cn--1980--p01", "cn--1982--p01"]},
  {id:"cn--1981--p02",track:"cn",year:1981,yearApprox:false,dim:"politics",weight:3,title:"叶剑英提出和平统一九条方针",summary:"1981年9月30日叶剑英向新华社记者阐明台湾回归祖国的九条方针政策。",detail:{background:"1979年《告台湾同胞书》提出通邮、通航、通商后，两岸民间往来仍未开放；1981年国庆前后中央需要把和平统一的具体政策系统化并对外说明。",process:"1981年9月30日，全国人大常委会委员长叶剑英向新华社记者阐明关于台湾回归祖国、实现和平统一的九条方针政策，建议举行国共两党对等谈判、实现第三次合作，提出通邮通商通航和旅游参观、经济文化交流，并说明国家实现统一后台湾可作为特别行政区、享有高度自治权、可保留军队；1981年10月1日《人民日报》全文发表这一谈话。",impact:"据《邓小平文选》第三卷的编注与相关谈话，1982年1月邓小平把九条方针概括为“一个国家，两种制度”的雏形表述；1982年12月现行宪法第31条规定国家在必要时得设立特别行政区，使这一构想获得宪法上的实现形式。",figures:["叶剑英"],place:"北京",state:"中华人民共和国",sources:["叶剑英《关于台湾回归祖国，实现和平统一的方针政策》（1981年9月30日）、《人民日报》1981年10月1日"],"tags":["九条方针","特别行政区","两岸关系"]},related:["cn--1979--p02", "cn--1983--p02"]},
  {id:"cn--1981--e01",track:"cn",year:1981,yearApprox:false,dim:"economy",weight:2,title:"国家恢复发行国库券",summary:"1981年1月16日国务院颁布《国库券条例》，当年开始发行。",detail:{background:"1979年、1980年中央财政连续出现较大赤字（据财政部公布的年度决算）；为筹集建设资金、平衡财政收支，中央决定恢复国内公债形式。",process:"1981年1月16日，国务院颁布《中华人民共和国国库券条例》，规定国库券由财政部统一发行、不得当作货币流通、不得自由买卖，并规定利率与分年偿还办法；发行对象以国营企业、事业单位和机关团体为主，同时向农村个人与城镇居民分配认购。",impact:"据财政部《中国财政年鉴》所载历年国债发行资料，1981年至1997年国家连续发行国库券，国家信用重新成为财政与宏观调控的工具；1994年起财政部陆续发行记帐式国债，二级市场与托管结算制度随之建立。",figures:["李先念"],place:"北京",state:"中华人民共和国",sources:["国务院《中华人民共和国国库券条例》（1981年1月16日颁布）、财政部编《中国财政年鉴》"],"tags":["国库券","财政赤字","国家信用"]},related:["cn--1980--i02", "cn--1981--p01"]},
  {id:"cn--1981--c01",track:"cn",year:1981,yearApprox:false,dim:"culture",weight:3,title:"“五讲四美”文明礼貌活动倡议",summary:"1981年2月25日九个团体联合倡议开展“五讲”“四美”活动。",detail:{background:"1979年后社会风气与公共秩序问题受到关注，工会、共青团与教育系统率先在青年中提倡讲文明、讲礼貌；中央把这一问题纳入精神文明建设的议程。",process:"1981年2月25日，中华全国总工会、共青团中央等九个团体联合发表《关于开展文明礼貌活动的倡议》，提出在人民内部特别是青少年中开展“五讲”（讲文明、讲礼貌、讲卫生、讲秩序、讲道德）与“四美”（心灵美、语言美、行为美、环境美）活动；3月起各地组织检查卫生、维护公共秩序的群众性活动。",impact:"据《十二大以来重要文献选编》与群团组织资料，1982年2月中央确定每年3月开展“文明礼貌月”活动，1983年又增加“三热爱”（热爱祖国、热爱社会主义、热爱中国共产党）内容，形成“五讲四美三热爱”的统一提法，并成立全国性活动委员会，1986年十二届六中全会就此作出精神文明建设决议。",figures:["中华全国总工会","共青团中央"],place:"北京",state:"中华人民共和国",sources:["九个团体《关于开展文明礼貌活动的倡议》（1981年2月25日）、《人民日报》1981年2月26日"],"tags":["五讲四美","文明礼貌月","社会风气"]},related:["cn--1981--p01", "cn--1986--p01"]},
  {id:"cn--1981--s01",track:"cn",year:1981,yearApprox:false,dim:"science",weight:3,title:"中国首次实现“一箭三星”发射",summary:"1981年9月20日用一枚火箭成功发射三颗空间物理探测卫星。",detail:{background:"1978年全国科学大会把返回式卫星与多星发射列入重点攻关项目；多星发射需要在同一枚火箭上解决分别定向分离、姿态控制与卫星供电跟踪等一系列技术问题。",process:"1981年9月20日，中国用一枚“风暴一号”运载火箭成功发射3颗空间物理探测卫星，卫星按预定程序分别与火箭脱离并进入各自轨道，据《当代中国的航天事业》记载，该型火箭由上海研制，这次发射使中国成为少数掌握一箭多星发射技术的国家之一。",impact:"这次发射与此前已多次成功的返回式卫星试验，共同构成我国运载火箭与卫星系列化的技术积累；据同一书记载，1982年1月“风暴一号”再次发射卫星，为该型火箭的最后一次飞行。",figures:["宋健"],place:"甘肃酒泉（发射场）",state:"中华人民共和国",sources:["新华社1981年9月21日报道、《当代中国的航天事业》（中国社会科学出版社1992年）"],"tags":["一箭多星","空间物理探测卫星","运载火箭"]},related:["cn--1970--s01", "cn--1978--s01"]},
  {id:"cn--1981--m01",track:"cn",year:1981,yearApprox:false,dim:"military",weight:3,title:"北京部队空军举行华北大演习",summary:"1981年9月30日华北大演习结束，邓小平等检阅受阅部队并发表讲话。",detail:{background:"1977年至1980年军队重申训练与编制整顿，围绕现代条件下诸军兵种合同作战组织演练；此次演习由总参谋部、总政治部等部门组织实施。",process:"1981年9月，北京部队与空军部队在华北某地举行合同战术演习，演练模拟敌情下的抗登陆与进攻作战；9月30日演习结束，邓小平与叶剑英、徐向前、聂荣臻等前往观看，检阅演习部队并发表讲话，提出把我军建设成为一支强大的现代化、正规化的革命军队。",impact:"据《中国人民解放军军史》的记载，这是“文化大革命”结束后解放军规模较大的一次合同演习，此后全军各大单位相继组织演习与集训；以现代化为中心的整军思路，为1985年中央军委扩大会议决定裁减军队员额一百万作了准备。",figures:["邓小平","叶剑英","徐向前","聂荣臻"],place:"华北某地（北京部队、空军部队演习区）",state:"中华人民共和国",sources:["《人民日报》1981年10月1日、《中国人民解放军军史》（军事科学出版社2010年）"],"tags":["华北大演习","合同演习","军队现代化"]},related:["cn--1980--m01", "cn--1985--p01"]},
  {id:"cn--1982--i01",track:"cn",year:1982,yearApprox:false,dim:"institution",weight:5,title:"现行宪法通过",summary:"1982年12月4日五届全国人大五次会议通过宪法，共4章138条。",detail:{background:"1980年9月五届全国人大三次会议决定修改宪法并成立宪法修改委员会，彭真主持日常工作；修改草案于1982年4月公布后交付全民讨论4个月，据全国人大常委会法制工作委员会的记述，讨论中提出的修改补充意见数量众多。",process:"1982年11月26日至12月10日，第五届全国人民代表大会第五次会议在北京举行，12月4日通过《中华人民共和国宪法》，共4章138条；宪法恢复设立国家主席、副主席，规定国务院实行总理负责制、县级以上地方各级人大设立常委会，规定农村人民公社须实行政社分开，承认城乡劳动者个体经济是社会主义公有制经济的补充，并在第31条规定国家在必要时得设立特别行政区。",impact:"这部宪法即我国现行宪法，此后由第七、八、九、十、十三届全国人民代表大会分别于1988年、1993年、1999年、2004年、2018年以修正案方式加以补充（据全国人民代表大会公布的修正案文本）；1982年宪法确立的国家机构框架沿用至今。",figures:["彭真","叶剑英","习仲勋"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法》（1982年12月4日第五届全国人民代表大会第五次会议通过）、《彭真文选（1941—1990）》（人民出版社1992年）"],"tags":["1982年宪法","现行宪法","特别行政区"]},related:["cn--1978--i01", "cn--1979--p02", "cn--1982--p01"]},
  {id:"cn--1982--p01",track:"cn",year:1982,yearApprox:false,dim:"politics",weight:4,title:"中共十二大提出“建设有中国特色的社会主义”",summary:"1982年9月1日至11日十二大召开，邓小平在开幕词中提出这一命题。",detail:{background:"1980年十一届五中全会决定提前召开第十二次全国代表大会；1981年历史决议完成后，党内对指导思想的争论基本平息。",process:"1982年9月1日至11日，中国共产党第十二次全国代表大会在北京举行，邓小平在开幕词中提出“把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义”；大会通过新的《中国共产党章程》，规定不设中央委员会主席、副主席而设总书记，并决定设立中央顾问委员会与中央纪律检查委员会；大会提出从1981年到20世纪末的20年，力争使全国工农业年总产值在提高经济效益的前提下翻两番。",impact:"据大会文件与十二届一中全会公报，“建设有中国特色的社会主义”成为改革开放新时期的主题；1982年9月12日一中全会选举胡耀邦为中央委员会总书记，邓小平为中央军事委员会主席，陈云为中央纪律检查委员会第一书记。",figures:["邓小平","胡耀邦","陈云","李先念"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第三卷《中国共产党第十二次全国代表大会开幕词》（1982年9月1日）、《十二大以来重要文献选编》（人民出版社1986年）"],"tags":["中共十二大","翻两番","中央顾问委员会"]},related:["cn--1982--i01", "cn--1987--p01"]},
  {id:"cn--1982--p02",track:"cn",year:1982,yearApprox:false,dim:"politics",weight:3,title:"中美发表八·一七公报",summary:"1982年8月17日中美发表第三个联合公报，涉及美国对台军售。",detail:{background:"1979年中美建交后，美国对台武器销售问题悬而未决；1981年至1982年美国酝酿再次向台湾出售武器，中方通过外交渠道多次交涉。",process:"1982年8月17日，中美两国同时发表《中华人民共和国和美利坚合众国联合公报》，即第三个联合公报；公报重申上海公报与建交公报确立的指导原则，美国政府声明它不寻求执行一项长期向台湾出售武器的政策，表示向台湾出售的武器在性能和数量上不超过建交以来近几年的水平，准备逐步减少，并声明不寻求干涉中国内政、不寻求长期售武的立场；中国政府重申解决台湾问题是中国内政。",impact:"据外交部公布的三个联合文本文本，八·一七公报与上海公报、建交公报共同构成中美关系的政治基础；此后两国在对台军售问题上仍时有分歧，但双方经贸、科技与人文往来在这一时期继续扩大。",figures:["邓小平","里根"],place:"北京、华盛顿",state:"中华人民共和国",sources:["《中华人民共和国和美利坚合众国联合公报》（1982年8月17日发表）、中华人民共和国外交部编《中国外交》（世界知识出版社历年版）"],"tags":["八·一七公报","对台军售","三个联合公报"]},related:["cn--1979--p01", "cn--1972--p01", "world--1982--p01"]},
  {id:"cn--1982--i02",track:"cn",year:1982,yearApprox:false,dim:"institution",weight:3,title:"国务院机构改革方案获批准",summary:"1982年3月8日人大常委会通过决议，批准国务院机构改革方案。",detail:{background:"1979年至1981年国务院行政机构增多、层次重叠，干部副职过多；1982年1月中央政治局会议讨论机构改革方案，邓小平在2月的讲话中称精简机构是一场革命。",process:"1982年3月8日，第五届全国人民代表大会常务委员会第二十二次会议通过《关于国务院机构改革问题的决议》，批准《国务院机构改革方案》，规定减少部委数量与副职、明确人员编制与领导职务退休年龄，并决定把经国务院批准的国家进出口管理委员会、外国投资管理委员会等并入对外经济贸易部等机构；据国务院公布的资料，改革后国务院行政机构由1981年的100个减为61个。",impact:"这次改革第一次把废除干部领导职务实际存在的终身制写入制度安排，并推动干部队伍革命化、年轻化、知识化、专业化；此后又进行1988年、1993年、1998年、2003年、2008年、2013年、2018年、2023年多次机构改革（据历次全国人民代表大会批准的国务院机构改革方案）。",figures:["邓小平","赵紫阳"],place:"北京",state:"中华人民共和国",sources:["《关于国务院机构改革问题的决议》（1982年3月8日第五届全国人大常委会第二十二次会议通过）、《三中全会以来重要文献选编》（人民出版社1982年）"],"tags":["国务院机构改革","干部四化","编制精简"]},related:["cn--1980--i02", "cn--1982--p01"]},
  {id:"cn--1982--e01",track:"cn",year:1982,yearApprox:false,dim:"economy",weight:3,title:"第一个中央一号文件确认责任制",summary:"1982年1月1日中央批转《全国农村工作会议纪要》，为1982年一号文件。",detail:{background:"1980年中央75号文件只承认贫困地区可以包产到户；到1981年下半年，全国多数地区已推行各种形式的联产承包，中央需要给出统一结论。",process:"1981年10月至11月中央召开农村工作会议形成纪要，1982年1月1日中共中央批转《全国农村工作会议纪要》，作为1982年中央一号文件（中发〔1982〕1号）印发；文件指出，包括包产到户、包干到户在内的各种责任制形式，都是社会主义集体经济的生产责任制，并强调只要群众不要求改变就不要变动。",impact:"这是改革开放后以“中央一号文件”名义连续部署农村工作的开端；据农牧渔业部公布的统计资料，到1982年底全国实行包产到户、包干到户的生产队已占总数九成以上，1983年1月中央接着印发第二个一号文件《当前农村经济政策的若干问题》。",figures:["胡耀邦","万里","邓小平"],place:"北京",state:"中华人民共和国",sources:["中共中央批转《全国农村工作会议纪要》（中发〔1982〕1号，1982年1月1日）、《三中全会以来重要文献选编》（人民出版社1982年）"],"tags":["中央一号文件","包干到户","生产责任制"]},related:["cn--1980--e02", "cn--1983--e01"]},
  {id:"cn--1982--c01",track:"cn",year:1982,yearApprox:false,dim:"culture",weight:2,title:"第一届茅盾文学奖揭晓",summary:"1982年6月首届茅盾文学奖评奖揭晓，奖励长篇小说创作。",detail:{background:"1977年至1981年长篇小说创作恢复，茅盾于1981年捐资倡导设立以己名命名的文学奖，由中国作家协会主办，奖励1977年至1981年间出版的长篇小说。",process:"1982年6月，第一届茅盾文学奖揭晓，《许茂和他的女儿们》（周克芹）、《东方》（魏巍）、《将军吟》（莫应丰）、《冬天里的春天》（李国文）、《芙蓉镇》（古华）等获首届奖；评奖由中国作家协会组织作家评论家投票，获奖作品随后由人民文学出版社等出版并印行大量册数。",impact:"据中国作家协会公布的评奖条例，茅盾文学奖此后陆续评选，1985年揭晓第二届，2005年起评奖周期固定为每四年一届，成为当代中国长篇小说创作最重要的常设奖项之一，获奖作品多被改编为影视与舞台剧。",figures:["茅盾","周克芹","古华"],place:"北京",state:"中华人民共和国",sources:["中国作家协会第一届茅盾文学奖评奖公告、《人民日报》1982年相关报道"],"tags":["茅盾文学奖","长篇小说","新时期文学"]},related:["cn--1977--c01", "cn--1979--c01"]},
  {id:"cn--1983--e01",track:"cn",year:1983,yearApprox:false,dim:"economy",weight:3,title:"第二个中央一号文件论联产承包",summary:"1983年1月中央印发《当前农村经济政策的若干问题》。",detail:{background:"1982年第一个一号文件后，农村商品流通不畅、社队企业管理与供销社体制等问题突出，承包制的理论地位也仍需说明。",process:"1983年1月，中共中央印发《当前农村经济政策的若干问题》（中发〔1983〕1号），作为第二个中央一号文件；文件从理论上说明联产承包责任制“是在党的领导下我国农民的伟大创造，是马克思主义农业合作化理论在我国实践中的新发展”，并就农、林、牧、副、渔全面发展，改革农村商品流通体制、供销社体制与农业技术改造等问题作出规定。",impact:"据农牧渔业部1983年公布的情况汇总，包干到户此后成为农村主要经营形式，集体统一经营体制随之结束；1983年10月中共中央、国务院发出《关于实行政社分开建立乡政府的通知》，到1984年底全国农村基本完成建乡工作。",figures:["胡耀邦","万里"],place:"北京",state:"中华人民共和国",sources:["中共中央《当前农村经济政策的若干问题》（中发〔1983〕1号，1983年1月印发）、《十二大以来重要文献选编》（人民出版社1986年）"],"tags":["一号文件","联产承包","商品流通"]},related:["cn--1982--e01", "cn--1983--i01"]},
  {id:"cn--1983--p01",track:"cn",year:1983,yearApprox:false,dim:"politics",weight:3,title:"六届全国人大一次会议组成国家机构",summary:"1983年6月6日至21日会议按新宪法选举、任命国家领导人。",detail:{background:"1982年12月宪法恢复国家主席建制并规定国务院实行总理负责制；1983年6月第六届全国人民代表大会第一次会议按新宪法组建国家机构。",process:"1983年6月6日至21日，第六届全国人民代表大会第一次会议在北京举行，选举李先念为中华人民共和国主席、乌兰夫为副主席，决定赵紫阳为国务院总理，选举彭真为全国人民代表大会常务委员会委员长；6月18日至20日举行的中国人民政治协商会议第六届全国委员会第一次会议选举邓颖超为全国政协主席。",impact:"这是按照1982年宪法首次组建国家机构，与1982年设立的中央顾问委员会共同构成邓小平提出的废除干部领导职务实际终身制的过渡安排；会议还听取并审议了政府工作报告与国民经济和社会发展计划报告。",figures:["李先念","赵紫阳","彭真","邓颖超","乌兰夫"],place:"北京",state:"中华人民共和国",sources:["第六届全国人民代表大会第一次会议公报（1983年6月21日）、《人民日报》1983年6月22日"],"tags":["六届全国人大一次会议","国家机构换届","总理负责制"]},related:["cn--1982--i01", "cn--1982--p01"]},
  {id:"cn--1983--p02",track:"cn",year:1983,yearApprox:false,dim:"politics",weight:3,title:"邓小平系统阐述统一构想",summary:"1983年6月26日邓小平提出大陆与台湾和平统一的六条设想。",detail:{background:"1981年叶剑英提出九条方针后需要在对外交往中进一步解释；1982年9月中英关于香港问题的谈判已经开始，台湾问题的提法也需明确界限。",process:"1983年6月26日，邓小平在会见美国新泽西州西东大学教授杨力宇时系统阐述祖国统一的设想，谈话以《中国大陆和台湾和平统一的设想》为题收入《邓小平文选》第三卷；他指出统一后台湾可以实行不同于大陆的社会制度，可以享有高度自治、可以保留自己的军队，中央不派人员去管理台湾，但反对“完全自治”与“两个半中国”的提法。",impact:"1984年6月邓小平在会见香港有关人士时把这一系列设想明确概括为“一个国家，两种制度”；据《邓小平文选》第三卷的篇目编排，这一构想在1984年至1985年间多次被用于解释香港、澳门与台湾问题，并成为1997年7月1日、1999年12月20日两地回归的制度基础。",figures:["邓小平","杨力宇"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第三卷《中国大陆和台湾和平统一的设想》（1983年6月26日）、《邓小平文选》第三卷《一个国家，两种制度》（1984年6月）"],"tags":["一国两制","高度自治","祖国统一"]},related:["cn--1981--p02", "cn--1984--p01", "world--1984--p02"]},
  {id:"cn--1983--i01",track:"cn",year:1983,yearApprox:false,dim:"institution",weight:4,title:"中央决定政社分开建立乡政府",summary:"1983年10月12日中共中央、国务院发出政社分开的通知。",detail:{background:"1958年后农村长期实行政社合一的人民公社体制；1980年四川广汉已出现摘下人民公社牌子的试点，1982年宪法规定人民公社须实行政社分开。",process:"1983年10月12日，中共中央、国务院发出《关于实行政社分开建立乡政府的通知》，规定把人民公社的政权职能与经济职能分开，建立乡、民族乡、镇人民政府作为农村基层政权，同时按乡建立乡党委，并根据生产的需要和群众的意愿逐步建立经济组织；通知要求在试点基础上分期分批推开，并规定村民委员会作为基层群众性自治组织。",impact:"据民政部关于建乡工作的总结资料，到1984年底全国农村政社合一的人民公社体制基本结束，乡（镇）人民政府取代公社管理委员会；同期各地普遍建立村民委员会，1987年11月24日六届全国人大常委会第二十三次会议通过《中华人民共和国村民委员会组织法（试行）》。",figures:["赵紫阳","万里"],place:"北京（在全国农村推行）",state:"中华人民共和国",sources:["中共中央、国务院《关于实行政社分开建立乡政府的通知》（1983年10月12日）、《十二大以来重要文献选编》（人民出版社1986年）"],"tags":["政社分开","人民公社结束","乡政府"]},related:["cn--1983--e01", "cn--1987--i01"]},
  {id:"cn--1983--s01",track:"cn",year:1983,yearApprox:false,dim:"science",weight:3,title:"“银河—Ⅰ”亿次巨型计算机鉴定",summary:"1983年12月国防科技大学研制的亿次巨型计算机通过国家鉴定。",detail:{background:"1978年全国科学大会把大型计算机与向量处理技术列入重点攻关项目；石油地震资料处理与中期天气预报当时的计算量已超出国产常规计算机的能力。",process:"1983年12月，国防科学技术大学研制的“银河—Ⅰ”巨型计算机通过国家鉴定，运算速度达到每秒一亿次以上，采用并行处理与向量指令结构，总设计师为慈云桂；这是我国第一台每秒运算亿次以上的大型计算机系统。",impact:"据《当代中国的电子工业》与国防科技大学校史资料，这台机器此后用于石油勘探数据处理与气象预报等领域，使中国成为当时少数能够独立研制亿次巨型计算机的国家之一；1992年11月“银河—Ⅱ”十亿次巨型计算机在长沙研制成功。",figures:["慈云桂"],place:"湖南长沙",state:"中华人民共和国",sources:["《人民日报》1983年12月关于“银河—Ⅰ”通过国家鉴定的报道、《当代中国的电子工业》（中国社会科学出版社1989年）"],"tags":["巨型计算机","银河一号","国防科技大学"]},related:["cn--1978--s01", "cn--1983--i01"]},
  {id:"cn--1984--i01",track:"cn",year:1984,yearApprox:false,dim:"institution",weight:4,title:"十二届三中全会通过经济体制改革决定",summary:"1984年10月20日全会通过《中共中央关于经济体制改革的决定》。",detail:{background:"1979年至1983年农村改革与扩大企业自主权试点推进，1982年十二大提出“计划经济为主、市场调节为辅”；1984年农村剩余劳动力转移与城市企业效率问题使改革重心转向城市。",process:"1984年10月20日，中国共产党第十二届中央委员会第三次全体会议在北京举行，通过《中共中央关于经济体制改革的决定》；决定提出改革是社会主义制度的自我完善，明确我国计划经济是在公有制基础上的有计划的商品经济，并把增强企业活力作为经济体制改革的中心环节，部署价格体系改革、政企职责分开与扩大企业自主权等任务。",impact:"这一决定为1985年放开农产品统购派购、推行企业承包经营责任制和工资改革提供了依据；1992年10月中共十四大确立社会主义市场经济体制的改革目标，与决定对商品经济的承认相衔接（据《江泽民文选》第一卷十四大报告）。",figures:["胡耀邦","赵紫阳","邓力群"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于经济体制改革的决定》（1984年10月20日中国共产党第十二届中央委员会第三次全体会议通过，人民出版社1984年）、《十二大以来重要文献选编》（人民出版社1986年）"],"tags":["十二届三中全会","有计划的商品经济","企业活力"]},related:["cn--1982--p01", "cn--1985--e01"]},
  {id:"cn--1984--e01",track:"cn",year:1984,yearApprox:false,dim:"economy",weight:3,title:"进一步开放14个沿海港口城市",summary:"1984年5月4日中央批转沿海部分城市座谈会纪要，宣布开放决定。",detail:{background:"1980年设立4个经济特区后，中央认为需要把开放政策延伸到工业基础较好、交通便利的沿海港口城市；1984年2月至3月邓小平视察深圳、珠海、厦门与上海等地后提出扩大开放的意见。",process:"1984年3月26日至4月6日，中共中央、国务院召开沿海部分城市座谈会；5月4日中央批转座谈会纪要，决定进一步开放大连、秦皇岛、天津、烟台、青岛、连云港、南通、上海、宁波、温州、福州、广州、湛江、北海等14个沿海港口城市，给予它们扩大利用外资、引进技术的自主权，并准许在有条件的地点辟建经济技术开发区。",impact:"据国家统计局历年《中国统计年鉴》的对外经济贸易数据，14个沿海城市与经济特区、随后开辟的长江三角洲、珠江三角洲、闽南三角地区经济开放区共同构成1980年代的开放格局；1988年4月海南建省并成为经济特区，1990年4月宣布开发开放浦东。",figures:["邓小平","谷牧"],place:"北京及大连、天津、上海、广州等14个城市",state:"中华人民共和国",sources:["中共中央、国务院批转《沿海部分城市座谈会纪要》（1984年5月4日）、国家统计局编《中国统计年鉴》"],"tags":["沿海开放城市","经济技术开发区","利用外资"]},related:["cn--1980--e03", "cn--1990--e01", "world--1984--e01"]},
  {id:"cn--1984--p01",track:"cn",year:1984,yearApprox:false,dim:"politics",weight:4,title:"中英签署关于香港问题的联合声明",summary:"1984年12月19日两国政府在北京正式签署联合声明及其附件。",detail:{background:"1982年9月24日邓小平会见英国首相撒切尔夫人，双方就1997年后香港的管治问题交锋；此后两国自1982年10月至1984年9月举行22轮会谈，其间曾因1983年9月的港元危机与“治权”之争而进展迟缓。",process:"1984年9月26日，两国政府代表团完成联合声明及两个附件的全部磋商并草签；1984年12月19日，国务院总理赵紫阳与英国首相撒切尔夫人正式签署《中华人民共和国政府和大不列颠及北爱尔兰联合王国政府关于香港问题的联合声明》；声明确认中华人民共和国政府于1997年7月1日对香港恢复行使主权，并在附件一中写入在社会、经济制度不变、法律基本不变等条件下设立直辖于中央人民政府的香港特别行政区的基本方针政策。",impact:"联合声明以外交文件形式解决了历史遗留的香港问题，1985年5月27日双方在北京互换批准书后声明生效；1990年4月11日第七届全国人民代表大会第三次会议通过《中华人民共和国香港特别行政区基本法》，把声明中的基本方针政策以法律形式固定下来。",figures:["邓小平","撒切尔夫人","赵紫阳","周南"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国政府和大不列颠及北爱尔兰联合王国政府关于香港问题的联合声明》（1984年12月19日签署）、新华社1984年12月20日报道"],"tags":["中英联合声明","一国两制","香港回归"]},related:["cn--1983--p02", "cn--1987--p02", "cn--1997--p01", "world--1984--p02"]},
  {id:"cn--1984--m01",track:"cn",year:1984,yearApprox:false,dim:"military",weight:3,title:"国庆35周年阅兵首次公开展示战略导弹",summary:"1984年10月1日邓小平检阅受阅部队，“东风五号”首次公开。",detail:{background:"1980年洲际火箭全程飞行试验与1981年华北大演习之后，军队装备与编制整顿的成果需要一次集中展示；1984年是中华人民共和国成立35周年。",process:"1984年10月1日，首都北京举行庆祝中华人民共和国成立35周年国庆阅兵和群众游行，中央军委主席邓小平乘车检阅受阅部队并发表讲话，阅兵总指挥为秦基伟；受阅方队中地面导弹部队首次公开“东风五号”战略导弹，海军、空军与三军仪仗队等一同受阅。",impact:"据《中国人民解放军军史》的记载，这是自1960年国庆阅兵之后再次在首都举行国庆阅兵，也是改革开放后军队现代化成果的第一次公开展示；同年百万裁军的决策进入实施阶段，阅兵与整军共同体现以经济建设为中心时期的国防政策调整。",figures:["邓小平","秦基伟"],place:"北京天安门广场",state:"中华人民共和国",sources:["《人民日报》1984年10月2日、《中国人民解放军军史》（军事科学出版社2010年）"],"tags":["国庆35周年","阅兵","战略导弹"]},related:["cn--1980--m01", "cn--1985--p01"]},
  {id:"cn--1984--s01",track:"cn",year:1984,yearApprox:false,dim:"science",weight:3,title:"中国发射第一颗试验通信卫星",summary:"1984年4月8日发射试验通信卫星，4月16日定点地球同步轨道。",detail:{background:"通信、广播与电视转播需要地球静止轨道卫星，这对火箭第三级低温发动机与卫星定点控制技术提出新要求；1984年1月29日中国发射试验通信卫星未能准确进入预定轨道。",process:"1984年4月8日，中国用自主研制的“长征三号”运载火箭在西昌卫星发射中心发射试验通信卫星，火箭第三级氢氧发动机二次启动成功，卫星于4月16日准确定点于赤道上空地球同步轨道，随后进行通信、电视传输试验。",impact:"据《当代中国的航天事业》的记载，这次发射与定点使中国成为少数能够独立发射地球静止轨道卫星的国家之一，我国卫星通信与电视广播自此具备国内组网条件；1986年2月1日“东方红二号”实用通信广播卫星发射定点，1988年3月发射第一颗气象卫星“风云一号”。",figures:["谢光选"],place:"四川西昌卫星发射中心",state:"中华人民共和国",sources:["新华社1984年4月18日报道、《当代中国的航天事业》（中国社会科学出版社1992年）"],"tags":["试验通信卫星","长征三号","地球同步轨道"]},related:["cn--1970--s01", "cn--1981--s01"]},
  {id:"cn--1984--x01",track:"cn",year:1984,yearApprox:false,dim:"explore",weight:2,title:"中国首次南极考察队出发",summary:"1984年11月20日考察队赴南极乔治王岛选址建站。",detail:{background:"1983年6月中国加入《南极条约》；要开展南极科学考察并取得协商国地位，需要自建常年考察站，中央于1984年批准组建首支南极考察队。",process:"1984年11月20日，中国第一支南极考察队乘船自上海出发，队中包括科学考察、工程设计施工与运输保障力量；12月31日考察队抵达南极洲南设得兰群岛的乔治王岛，随即在南极夏季的低温与强风条件下开始站址测量与施工。",impact:"这次考察与建站工程直接促成1985年2月长城站的建成，据国家海洋局的记述，中国于1986年10月被接纳为《南极条约》协商国；此后中国陆续建立中山站、昆仑站、泰山站与秦岭站，形成常年性的南极考察体系。",figures:["郭琨"],place:"上海出发，南极洲南设得兰群岛乔治王岛",state:"中华人民共和国",sources:["新华社1984年11月关于中国首次南极考察队出发的报道、国家海洋局编《中国的极地事业》资料"],"tags":["南极考察","长城站","南极条约"]},related:["cn--1984--s01", "cn--1985--x01", "world--1985--x01"]},
  {id:"cn--1984--c01",track:"cn",year:1984,yearApprox:false,dim:"culture",weight:3,title:"中国代表团参加洛杉矶奥运会",summary:"1984年7月29日许海峰夺得中国首枚奥运会金牌。",detail:{background:"国际奥委会1979年通过关于中国代表权的决议后，中国奥委会的合法席位得到恢复；1984年夏季奥运会在美国洛杉矶举行，中国派出代表团参加25个大项的比赛。",process:"1984年7月29日，许海峰在男子自选手枪慢射60发比赛中夺得冠军，这是中国运动员获得的第一枚奥运会金牌；本届奥运会上中国共获15枚金牌，列金牌榜第四位，体操运动员李宁获3枚金牌，中国女排继1981年世界杯、1982年世锦赛之后获得本届奥运会冠军，实现三连冠。",impact:"据国家体委编《中国体育年鉴》与当时的媒体报道，洛杉矶奥运会后“奥运战略”与业余体校、专业队、国家队三级训练网成为竞技体育体制的主干；1990年北京举办第11届亚洲运动会，2001年7月13日北京获得第29届夏季奥林匹克运动会举办权。",figures:["许海峰","李宁","袁伟民"],place:"美国洛杉矶",state:"中华人民共和国",sources:["新华社1984年7月30日报道、国家体委编《中国体育年鉴（1984）》（人民体育出版社）"],"tags":["洛杉矶奥运会","首枚金牌","竞技体育体制"]},related:["cn--2008--c01", "cn--1981--p01", "world--1984--p03"]},
  {id:"cn--1985--e01",track:"cn",year:1985,yearApprox:false,dim:"economy",weight:4,title:"中央一号文件取消农产品统购派购",summary:"1985年1月中央规定农产品不再下达统购派购任务，改行合同定购。",detail:{background:"1984年农业增产之后部分地区出现卖粮难，财政对购销倒挂的补贴负担加重；农产品流通的双轨问题在1984年经济体制改革决定中已被提出。",process:"1985年1月，中共中央、国务院印发《关于进一步活跃农村经济的十项政策》（中发〔1985〕1号），作为第四个中央一号文件；文件规定从1985年度起，除个别品种外国家不再向农民下达农产品统购派购任务，粮食、棉花改行合同定购，定购以外的部分可以自由上市，生猪、木材等派购品种先后放开，粮食定购按“倒三七”比例计价。",impact:"据国家统计局编《中国统计年鉴》所载农产品收购价格指数序列，取消统购派购使农村流通由计划转向市场，个体商业与乡镇企业在1985年至1988年间迅速扩张；因定购价格偏低与比较收益下降，1985年至1987年多次出现粮食定购困难，1990年国务院决定建立国家专项粮食储备制度。",figures:["胡耀邦","万里"],place:"北京",state:"中华人民共和国",sources:["中共中央、国务院《关于进一步活跃农村经济的十项政策》（中发〔1985〕1号，1985年1月印发）、国家统计局编《中国统计年鉴（1986）》"],"tags":["一号文件","合同定购","农产品流通"]},related:["cn--1984--i01", "cn--1985--e02"]},
  {id:"cn--1985--e02",track:"cn",year:1985,yearApprox:false,dim:"economy",weight:2,title:"机关事业单位与企业工资制度改革",summary:"1985年机关事业实行以职务工资为主的结构工资制，企业推行工效挂钩。",detail:{background:"1956年建立的等级工资制沿用近30年，机关、事业单位与企业工资标准交叉，平均主义与滥发奖金的现象并存。",process:"1985年，中共中央、国务院部署工资制度改革：对国家机关和事业单位工作人员实行以职务工资为主的结构工资制，把工资分为基础工资、职务工资、工龄津贴和奖励工资四个部分；对企业推行工资总额同经济效益挂钩的办法，职工工资随企业效益浮动，同时以奖金税等手段控制消费基金过快增长（据国务院工资制度改革小组的文件）。",impact:"据国家统计局的职工工资统计，1985年改革使职务与工资直接挂钩、当年职工平均工资明显提高，但结构工资制中的津贴部分未完全落实；1993年起机关、事业单位与企业工资制度再次分别改革，事业单位推行专业技术职务等级工资制。",figures:["赵紫阳"],place:"北京",state:"中华人民共和国",sources:["中共中央、国务院《关于国家机关和事业单位工作人员工资制度改革问题的通知》（1985年）、国家统计局编《中国统计年鉴（1986）》"],"tags":["结构工资制","工效挂钩","消费基金"]},related:["cn--1956--i02", "cn--1984--i01"]},
  {id:"cn--1985--p01",track:"cn",year:1985,yearApprox:false,dim:"politics",weight:4,title:"中央军委决定裁减军队员额一百万",summary:"1985年5月23日至6月6日军委扩大会议作出百万裁军决策。",detail:{background:"1975年至1980年军队多次精简，员额仍然偏大；1984年11月1日邓小平在中央军委座谈会上提出再减少军队员额100万的主张，会议同时确定军队建设指导思想的转变。",process:"1985年5月23日至6月6日，中央军事委员会召开扩大会议，决定裁减军队员额一百万，并把军队建设指导思想从立足于早打、大打、打核战争的临战准备，转到和平时期建设的轨道；会后全军按新编制进行整编，陆军军改编为集团军，一批机关、院校与省军区单位被撤销或合并，到1987年年底前精简整编基本完成。",impact:"据《中国人民解放军军史》的记载，经过这次调整，解放军总员额减至300万左右，军费中人员与生活费的比重下降；这一决策与此后1997年、2003年各裁减军队员额50万和20万、2015年宣布裁减30万共同构成1980年代以来以规模结构改革为主线的军队调整序列。",figures:["邓小平","杨尚昆"],place:"北京",state:"中华人民共和国",sources:["《邓小平文选》第三卷《军队要服从整个国家建设大局》（1984年11月1日）、新华社1985年6月关于中央军委扩大会议的报道"],"tags":["百万大裁军","军委扩大会议","集团军"]},related:["cn--1981--m01", "cn--1985--m01"]},
  {id:"cn--1985--m01",track:"cn",year:1985,yearApprox:false,dim:"military",weight:2,title:"国防大学组建",summary:"1985年7月由军事、政治、后勤三所学院合并组建国防大学。",detail:{background:"1980年代初培训中高级军官的军事学院、政治学院、后勤学院分设，学科重叠、编制庞大；百万裁军决策提出后军队院校同时调整。",process:"1985年7月，国防大学成立大会在北京举行，学校由原军事学院、政治学院、后勤学院合并组建，张震任校长、梁必业任政治委员，承担联合战役指挥与中高级军官、军事理论干部的培训任务。",impact:"据《中国人民解放军军史》，与国防大学组建相配合，1985年至1986年全军院校数量大幅压缩，形成以国防大学、各军兵种指挥与技术院校为骨干的培训体系；1986年军队实行职务编制军衔的试点，1988年9月恢复军衔制。",figures:["张震","梁必业"],place:"北京",state:"中华人民共和国",sources:["《人民日报》1985年7月关于国防大学成立的报道、《中国人民解放军军史》（军事科学出版社2010年）"],"tags":["国防大学","院校合并","军官培训"]},related:["cn--1985--p01", "cn--1988--m01"]},
  {id:"cn--1985--i01",track:"cn",year:1985,yearApprox:false,dim:"institution",weight:3,title:"中共中央作出教育体制改革的决定",summary:"1985年5月27日中央下发《关于教育体制改革的决定》，部署分级办学。",detail:{background:"1984年经济体制改革决定把科技、教育体制的改革列为任务；基础教育投资不足、管理权限集中，高等学校专业设置与企业需求脱节。",process:"1985年5月中旬全国教育工作会议召开后，5月27日中共中央下发《中共中央关于教育体制改革的决定》；决定提出教育必须为社会主义建设服务、社会主义建设必须依靠教育，把实行九年制义务教育的责任交给地方、分级管理，改革高等学校的招生计划与毕业生统一分配制度，扩大高校办学自主权，并调整中等教育结构、大力发展职业技术教育。",impact:"据国家教育委员会编《中国教育年鉴》，决定下发后各地开始分级实施“普九”并发展乡镇企业办学，1986年4月《义务教育法》以法律形式确认九年制义务教育；1993年2月中央印发《中国教育改革和发展纲要》，1995年5月提出实施科教兴国战略。",figures:["胡耀邦","邓小平","何东昌"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于教育体制改革的决定》（1985年5月27日中共中央下发，人民出版社1985年）、国家教育委员会编《中国教育年鉴（1985）》"],"tags":["教育体制改革","分级办学","职业技术教育"]},related:["cn--1986--i01", "cn--1980--i04"]},
  {id:"cn--1985--x01",track:"cn",year:1985,yearApprox:false,dim:"explore",weight:3,title:"中国第一个南极考察站长城站建成",summary:"1985年2月长城站在乔治王岛竣工，同年10月27日举行落成典礼。",detail:{background:"1984年11月中国首次南极考察队抵达南设得兰群岛乔治王岛，须在南极夏季结束前完成主体工程施工与设备调试。",process:"1985年2月，长城站工程竣工并具备越冬使用条件，站区位于乔治王岛菲尔德斯半岛南部，设有气象、地质、生物、海洋等实验室与通信、发电、淡水处理设施；1985年10月27日中国举行长城站落成典礼，来自二十多个国家的南极考察代表应邀出席。",impact:"长城站的建成使我国具备常年开展南极科学考察的基地，并促成1986年10月中国被接受为《南极条约》协商国；1989年1月中国在东南极拉斯曼丘陵建成中山站，2009年1月建成位于内陆冰盖的昆仑站，2014年2月建成泰山站，2024年2月建成秦岭站。",figures:["郭琨"],place:"南极洲南设得兰群岛乔治王岛",state:"中华人民共和国",sources:["新华社1985年10月关于长城站落成典礼的报道、国家海洋局编中国南极考察年度报告"],"tags":["长城站","南极考察站","科学考察"]},related:["cn--1984--x01", "cn--1986--x01", "world--1985--x01"]},
  {id:"cn--1985--c01",track:"cn",year:1985,yearApprox:false,dim:"culture",weight:2,title:"中国作家协会第四次会员代表大会",summary:"1985年11月作协四代会在北京召开，巴金当选中国作家协会主席。",detail:{background:"1979年第四次文代会后作家团体陆续恢复活动；1984年至1985年小说创作在题材与写法上变化明显，外国文学理论大量译介进来。",process:"1985年11月，中国作家协会第四次会员代表大会在北京召开，会议选举巴金为中国作家协会主席，改选理事会与书记处；同年在小说与理论界出现的实验性写作被文学史研究者概括为1985年的“方法年”，“寻根文学”与先锋小说在这一年前后相继成形。",impact:"据洪子诚《中国当代文学史》，1985年前后的写法探索改变了新时期文学由伤痕、反思题材主导的格局，莫言、韩少功、余华、苏童等作家的作品在此后十年陆续发表，1987年先锋小说进入创作高峰。",figures:["巴金","王蒙"],place:"北京",state:"中华人民共和国",sources:["中国作家协会第四次会员代表大会文件、《人民日报》1985年11月的报道","洪子诚《中国当代文学史》（北京大学出版社1999年）"],"tags":["中国作家协会","巴金","寻根文学"]},related:["cn--1979--c01", "cn--1982--c01"]},
  {id:"cn--1986--p01",track:"cn",year:1986,yearApprox:false,dim:"politics",weight:3,title:"十二届六中全会作出精神文明建设决议",summary:"1986年9月28日全会通过《中共中央关于社会主义精神文明建设指导方针的决议》。",detail:{background:"1981年起“五讲四美”活动持续开展，1983年增加“三热爱”内容；1985年至1986年围绕经济改革与思想领域出现的争论，中央需要就精神文明建设的指导方针作出系统决定。",process:"1986年9月28日，中国共产党第十二届中央委员会第六次全体会议在北京举行，通过《中共中央关于社会主义精神文明建设指导方针的决议》；决议指出社会主义精神文明是社会主义的重要特征，规定精神文明建设的根本任务是培育有理想、有道德、有文化、有纪律的公民，提高全民族的思想道德素质与教育科学文化素质，并强调坚持以经济体制改革为中心的同时推进政治体制改革与精神文明建设；全会同时决定1987年下半年召开中国共产党第十三次全国代表大会。",impact:"据决议文本与《人民日报》1986年9月29日社论，“四有”公民与“两个文明一起抓”成为此后宣传思想工作的常用表述；1996年10月十四届六中全会通过《中共中央关于加强社会主义精神文明建设若干重要问题的决议》，延续这一框架。",figures:["胡耀邦","邓小平"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于社会主义精神文明建设指导方针的决议》（人民出版社1986年）、《十二大以来重要文献选编》（下，人民出版社1988年）"],"tags":["十二届六中全会","四有公民","精神文明"]},related:["cn--1981--c01", "cn--1987--p01"]},
  {id:"cn--1986--i01",track:"cn",year:1986,yearApprox:false,dim:"institution",weight:3,title:"《中华人民共和国义务教育法》通过",summary:"1986年4月12日会议通过义务教育法，当年7月1日施行。",detail:{background:"1985年教育体制改革决定把发展基础教育的责任交给地方；当时全国青壮年文盲数量庞大，适龄儿童入学率与巩固率亟待以法律保障。",process:"1986年4月12日，第六届全国人民代表大会第四次会议通过《中华人民共和国义务教育法》，自1986年7月1日起施行；法律规定国家实行九年制义务教育，适龄儿童、少年免试就近入学，实施义务教育的学校不得收取学费，义务教育实行地方负责、分级管理的体制，经费由地方财政筹措、国家予以补助。",impact:"据教育部公布的验收资料，到2000年底全国普及九年义务教育的人口覆盖率超过85%，青壮年文盲率降到5%以下；2006年6月修订后的义务教育法确立经费保障机制，2008年秋季起全国城乡义务教育阶段学生全部免收学杂费。",figures:["彭真","何东昌"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国义务教育法》（1986年4月12日第六届全国人民代表大会第四次会议通过）、教育部编《中国教育年鉴（1986）》"],"tags":["义务教育法","免试就近入学","免收学费"]},related:["cn--1985--i01", "cn--1986--i02"]},
  {id:"cn--1986--i02",track:"cn",year:1986,yearApprox:false,dim:"institution",weight:3,title:"《中华人民共和国民法通则》通过",summary:"1986年4月12日会议通过民法通则，1987年1月1日施行。",detail:{background:"1979年至1982年民法起草曾形成三稿，因经济体制仍在变动，立法机关改为先制定单行法与通则；1985年在全国人大法律委员会主持下重新起草民法通则草案。",process:"1986年4月12日，第六届全国人民代表大会第四次会议通过《中华人民共和国民法通则》，自1987年1月1日起施行；通则规定公民的民事权利能力、民事行为能力与监护制度，确立法人的民事主体地位，就民事法律行为、代理、诉讼时效、违约责任与侵权责任作出规定，并明确个人合伙、个体工商户与农村承包经营户的民事地位，规定财产所有权与相邻关系、知识产权中的著作权、专利权、商标权受法律保护。",impact:"据最高人民法院的司法解释沿革资料，民法通则在此后三十多年间是民事审判的基本依据；1999年10月《合同法》、1986年《著作权法》、1993年《公司法》等单行法与之并行，2020年5月十三届全国人大三次会议通过《中华人民共和国民法典》，自2021年1月1日施行，民法通则同时废止。",figures:["彭真","王家福"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国民法通则》（1986年4月12日第六届全国人民代表大会第四次会议通过）、《彭真文选（1941—1990）》（人民出版社1992年）"],"tags":["民法通则","法人制度","民事责任"]},related:["cn--1979--i01", "cn--1986--i01"]},
  {id:"cn--1986--i03",track:"cn",year:1986,yearApprox:false,dim:"institution",weight:2,title:"企业破产法（试行）通过",summary:"1986年12月2日人大常委会通过企业破产法（试行），1988年8月1日生效。",detail:{background:"1984年扩大企业自主权后，亏损国营企业的退出问题被提出；1985年前后沈阳等地已出现关闭、资不抵债企业的处理案例，但缺少法律依据。",process:"1986年12月2日，第六届全国人民代表大会常务委员会第十八次会议通过《中华人民共和国企业破产法（试行）》，适用于全民所有制企业；法律规定企业因经营管理不善造成严重亏损、不能清偿到期债务的，依照本法宣告破产，并规定了破产申请的提出、债权人会议、和解与整顿程序以及破产财产的清偿顺序；该法自《中华人民共和国全民所有制工业企业法》施行之日起施行，即1988年8月1日起生效。",impact:"据最高人民法院与国家经济贸易委员会的公开资料，1988年至1993年破产程序的实际适用数量有限，1994年起在若干城市开展优化资本结构试点后案例增多；2006年8月27日十届全国人大常委会第二十四次会议通过新的《中华人民共和国企业破产法》，自2007年6月1日施行，适用范围扩大至所有企业法人。",figures:["彭真"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国企业破产法（试行）》（1986年12月2日第六届全国人大常委会第十八次会议通过）、《中华人民共和国法律汇编（1986）》（人民出版社）"],"tags":["企业破产法","清偿到期债务","国企改革"]},related:["cn--1984--i01", "cn--1986--i02"]},
  {id:"cn--1986--e01",track:"cn",year:1986,yearApprox:false,dim:"economy",weight:3,title:"中国申请恢复关贸总协定缔约国地位",summary:"1986年7月10日中国政府正式递交恢复缔约国地位的申请照会。",detail:{background:"中国曾是关税与贸易总协定的创始缔约国之一，1948年签相关议定书；1950年台湾当局非法宣告退出后长期未参加其活动，1971年缔约国撤销台湾当局的观察员资格。1986年经济体制改革决定提出对外开放要扩展到参与国际分工。",process:"1986年7月10日，中华人民共和国驻日内瓦外交代表向关税与贸易总协定总干事递交照会，正式申请恢复中国在该协定的缔约国地位，强调中国是申请“恢复”席位而不是重新加入，并表明以关税减表为谈判基础、以恢复关贸总协定成员资格促进对外经贸关系；同年中国政府派出由佟志广任团长的复关谈判代表团。",impact:"据世界贸易组织公布的文件与谈判纪要，1987年3月关贸总协定设立中国工作组，开始审议中国对外贸易制度；1995年1月世界贸易组织成立后谈判转为“入世”程序，2001年11月10日多哈会议通过中国加入决定，同年12月11日中国正式成为世界贸易组织成员。",figures:["佟志广","龙永图"],place:"日内瓦",state:"中华人民共和国",sources:["新华社1986年7月11日报道、世界贸易组织《中国加入世界贸易组织议定书》（2001年）"],"tags":["恢复缔约国地位","多边贸易体制","对外经贸"]},related:["cn--1984--e01", "cn--2001--e01"]},
  {id:"cn--1986--s01",track:"cn",year:1986,yearApprox:false,dim:"science",weight:4,title:"863计划：高技术研究发展纲要",summary:"1986年3月四位科学家提出建议，11月18日中央转发高技术发展纲要。",detail:{background:"1980年代中期主要国家相继提出高技术研究计划，跟踪世界高技术发展被科技界认为是紧迫课题；1986年3月，王大珩、王淦昌、杨嘉墀、陈芳允四位科学家联名向中央提出建议。",process:"1986年3月，四位科学家的建议经国家科委研究后报送中央，邓小平于当月批示“此事宜速作决断，不可拖延”；1986年11月18日，中共中央、国务院转发《高技术研究发展计划纲要》，选择生物技术、航天技术、信息技术、激光技术、自动化技术、能源技术和新材料7个领域作为重点，并设立国家高技术研究发展联合委员会与各领域专家委员会，实行首席科学家负责制。",impact:"据国家科学技术部的公开资料，这一计划此后按五个五年计划滚动实施，形成了我国高性能计算机、中文信息处理、载人航天与探月工程的前期技术积累；2014年国务院印发《关于深化财政科技计划管理改革的方案》，863计划与国家科技支撑计划等整合为国家重点研发计划。",figures:["邓小平","王大珩","王淦昌","杨嘉墀","陈芳允","宋健"],place:"北京",state:"中华人民共和国",sources:["中共中央、国务院《关于转发〈高技术研究发展计划纲要〉的通知》（1986年11月18日）、国家科学技术部编《中国科技统计年鉴》"],"tags":["863计划","生物技术","信息技术"]},related:["cn--1978--s01", "cn--1986--p01"]},
  {id:"cn--1986--x01",track:"cn",year:1986,yearApprox:false,dim:"explore",weight:2,title:"中国成为南极条约协商国",summary:"1986年10月中国被接受为《南极条约》协商国，取得表决权。",detail:{background:"按《南极条约》规定，只有派出了考察站或考察队的缔约国才能被接受为协商国并参加实质决策；1983年6月中国加入该条约，1985年2月长城站竣工。",process:"1986年10月，在《南极条约》协商国会议上中国被接受为协商国，从此可参与南极事务的决策与相关国际法律文件的制定；同年中国组织第二次南极考察，考察队继续承担长城站的越冬值守与科学观测任务。",impact:"据国家海洋局与《南极条约》秘书处公布的缔约国名单，成为协商国后中国可出席一年一度的协商国会议并参与相关国际法律文件的制定；1991年《关于环境保护的南极条约议定书》通过前后，中国均参加了缔约国的谈判进程。此后中国南极考察由单次夏季考察转为夏季建站与常年越冬值守并行的年度任务，考察船舶与后续考察站相继加入。",figures:["郭琨"],place:"南极洲乔治王岛长城站（中国考察基地）",state:"中华人民共和国",sources:["新华社1986年10月关于中国成为《南极条约》协商国的报道、《南极条约》缔约国名单（秘书处公布）"],"tags":["南极条约","协商国","极地考察"]},related:["cn--1985--x01", "cn--1989--x01"]},
  {id:"cn--1987--p01",track:"cn",year:1987,yearApprox:false,dim:"politics",weight:4,title:"中共十三大阐述社会主义初级阶段理论",summary:"1987年10月25日至11月1日大会提出基本路线与“三步走”战略。",detail:{background:"1986年9月十二届六中全会决定1987年下半年召开十三大；1987年前后围绕改革与经济发展战略、政治体制改革方案的组织起草同时进行。",process:"1987年10月25日至11月1日，中国共产党第十三次全国代表大会在北京举行，赵紫阳作《沿着有中国特色的社会主义道路前进》的报告；报告阐述我国社会仍处于社会主义初级阶段，把党在社会主义初级阶段的基本路线概括为以经济建设为中心、坚持四项基本原则、坚持改革开放，并提出经济发展“三步走”的部署：第一步使国民生产总值比1980年翻一番、解决温饱，第二步到20世纪末达到小康水平，第三步到21世纪中叶达到中等发达国家水平。",impact:"据大会文件与十三届一中全会公报，会议选举赵紫阳为中央委员会总书记，邓小平为中央军事委员会主席，并决定由陈云主持中央纪律检查委员会工作、邓小平任中央顾问委员会主任；据国家统计局公布的数据，国民生产总值比1980年翻一番的第一步目标在1987年提前实现。",figures:["赵紫阳","邓小平","万里"],place:"北京",state:"中华人民共和国",sources:["《沿着有中国特色的社会主义道路前进——加快改革开放和现代化建设》（1987年10月25日，人民出版社1987年）、《十三大以来重要文献选编》（上，人民出版社1991年）"],"tags":["中共十三大","社会主义初级阶段","三步走"]},related:["cn--1982--p01", "cn--1979--p03", "cn--1987--p03"]},
  {id:"cn--1987--p03",track:"cn",year:1987,yearApprox:false,dim:"politics",weight:3,title:"胡耀邦辞去中央委员会总书记职务",summary:"1987年1月16日中央政治局扩大会议公报公布这一人事决定。",detail:{background:"1986年底至1987年初部分高校出现学生罢课、上街的情况，中央在1987年1月召开政治局扩大会议，围绕思想政治工作的领导问题作出调整。",process:"1987年1月10日至15日，中共中央政治局举行扩大会议；1月16日公布的公报说，会议同意接受胡耀邦辞去中央委员会总书记职务的请求，并确认他仍在中央政治局常委内担任委员，决定由赵紫阳代理中央委员会总书记职务。",impact:"据《中国共产党历史》第二卷与当年《人民日报》的报道，这次调整发生于关于反对资产阶级自由化问题的争论之中；1989年4月15日胡耀邦因病逝世，此后新华社与各地报纸公开报道了各界的悼念活动。",figures:["胡耀邦","赵紫阳"],place:"北京",state:"中华人民共和国",sources:["中共中央政治局扩大会议公报（1987年1月16日）、《人民日报》1987年1月17日"],"tags":["政治局扩大会议","中央委员会总书记","1987年"]},related:["cn--1982--p01", "cn--1987--p01", "cn--1989--p01"]},
  {id:"cn--1987--p02",track:"cn",year:1987,yearApprox:false,dim:"politics",weight:3,title:"中葡签署关于澳门问题的联合声明",summary:"1987年4月13日两国政府总理在北京正式签署联合声明。",detail:{background:"1979年2月中葡建交时，双方在联合公报中确认澳门是葡萄牙占领下的中国领土，将在适当时候通过协商解决；1986年6月30日起至1987年3月，两国举行四轮会谈。",process:"1987年3月26日，两国政府代表在北京完成联合声明及两个附件的草签；1987年4月13日，国务院总理赵紫阳与葡萄牙总理席尔瓦正式签署《中华人民共和国政府和葡萄牙共和国政府关于澳门问题的联合声明》；声明确认中国政府于1999年12月20日对澳门恢复行使主权，并规定按“一个国家，两种制度”方针设立澳门特别行政区、保持其现行社会经济制度五十年不变。",impact:"1988年1月15日中葡双方在北京互换批准书，联合声明生效；1993年3月31日第八届全国人民代表大会第一次会议通过《中华人民共和国澳门特别行政区基本法》，1999年12月20日澳门回归并成立特别行政区。",figures:["赵紫阳","席尔瓦","邓小平"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国政府和葡萄牙共和国政府关于澳门问题的联合声明》（1987年4月13日签署）、新华社1987年4月14日报道"],"tags":["中葡联合声明","澳门回归","五十年不变"]},related:["cn--1984--p01", "cn--1999--p01", "world--1984--p02"]},
  {id:"cn--1987--i01",track:"cn",year:1987,yearApprox:false,dim:"institution",weight:3,title:"村民委员会组织法（试行）通过",summary:"1987年11月24日人大常委会通过该法，1988年6月1日起试行。",detail:{background:"1982年宪法已规定村民委员会是基层群众性自治组织，1983年起政社分开建立乡政府后，村委会的产生办法与职权需要专门法律；草案曾于1986年11月经人大常委会初次审议。",process:"1987年11月24日，第六届全国人民代表大会常务委员会第二十三次会议通过《中华人民共和国村民委员会组织法（试行）》，规定村民委员会是村民自我管理、自我教育、自我服务的基层群众性自治组织，村民委员会的主任、副主任和委员由村民直接选举产生，村里的重大事务由村民会议讨论决定，并规定村务公开与乡级人民政府对村委会的指导关系；该法自1988年6月1日起试行。",impact:"据民政部的基层政权建设统计，1990年代中期全国绝大多数建制村建立了村民委员会并实行直接选举；1998年11月4日九届全国人大常委会第五次会议通过正式的《中华人民共和国村民委员会组织法》，2010年10月修订后增加村务监督委员会与“四民主”程序的具体规定。",figures:["彭真"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国村民委员会组织法（试行）》（1987年11月24日第六届全国人大常委会第二十三次会议通过）、《彭真文选（1941—1990）》（人民出版社1992年）"],"tags":["村民委员会","基层群众自治","直接选举"]},related:["cn--1983--i01", "cn--1998--i01"]},
  {id:"cn--1987--e01",track:"cn",year:1987,yearApprox:false,dim:"economy",weight:3,title:"深圳首次公开拍卖国有土地使用权",summary:"1987年12月1日深圳以公开竞投方式出让一宗住宅用地使用权。",detail:{background:"1982年宪法规定城市的土地属于国家所有，1986年《土地管理法》施行后国有土地使用权如何出让缺少操作办法；深圳因建设用地紧缺先行探索。",process:"1987年12月1日，深圳市政府举行国有土地使用权公开拍卖大会，把一宗住宅建设用地的使用权以公开竞投方式出让给出价最高的广东省经济特区房地产公司，这是中华人民共和国成立后第一次以竞争方式有偿出让国有土地使用权，被称为土地拍卖“第一槌”。",impact:"这次试验直接推动宪法条文的修改：1988年4月12日第七届全国人民代表大会第一次会议通过的宪法修正案规定“土地的使用权可以依照法律的规定转让”；1990年5月国务院颁布《城镇国有土地使用权出让和转让暂行条例》，土地出让收入此后成为城市基础设施建设投资的重要来源，1992年至1993年中央还多次清理违规设立的各类开发区。",figures:["李灏"],place:"广东深圳",state:"中华人民共和国",sources:["新华社1987年12月关于深圳首次公开拍卖国有土地使用权的报道、1988年《中华人民共和国宪法修正案》（1988年4月12日通过）"],"tags":["土地使用权出让","土地拍卖","深圳试验"]},related:["cn--1980--e03", "cn--1988--i01"]},
  {id:"cn--1987--s01",track:"cn",year:1987,yearApprox:false,dim:"science",weight:2,title:"中国首次为国外提供卫星搭载服务",summary:"1987年8月5日发射返回式卫星，搭载法国微重力实验装置。",detail:{background:"1975年起中国已具备卫星返回能力；1980年代中期航天部门开始与法国等国商谈在返回式卫星上安装国外实验装置的合作。",process:"1987年8月5日，中国发射一颗返回式遥感卫星，卫星舱内安装了法国研制的微重力材料处理实验装置；1987年9月9日卫星按计划返回并在境内着陆，中法双方科技人员共同检查实验样品，这是中国第一次为国外用户提供卫星搭载实验服务。",impact:"据新华社与航天部门的公开记载，此次合作使我国返回式卫星开始进入国际商业服务领域，此后又为欧洲多国承担搭载实验；1990年4月7日中国用“长征三号”运载火箭成功发射美国制造的“亚洲一号”通信卫星，进入国际商业发射服务市场。",figures:["任新民","王希季"],place:"中国西北发射场（发射），四川境内（回收）",state:"中华人民共和国",sources:["新华社1987年8月与9月关于返回式卫星发射回收及中法微重力实验的报道、《当代中国的航天事业》（中国社会科学出版社1992年）"],"tags":["返回式卫星","中法合作","商业航天"]},related:["cn--1984--s01", "cn--1990--s01"]},
  {id:"cn--1988--p01",track:"cn",year:1988,yearApprox:false,dim:"politics",weight:4,title:"海南建省并设立经济特区",summary:"1988年4月13日大会决定设立海南省并建立海南经济特区。",detail:{background:"1987年8月国务院组织海南筹备组完成社会经济考察，同年9月向中央报送在海南岛建立大型经济特区的建议，12月把建省方案提请全国人民代表大会审议。",process:"1988年4月13日，第七届全国人民代表大会第一次会议通过《关于设立海南省的决定》和《关于建立海南经济特区的决议》，把原属广东省的海南行政区以及西沙群岛、南沙群岛、中沙群岛的岛礁及其海域划归海南省，全省陆地面积约3.4万平方公里，海南经济特区成为我国面积最大的经济特区；许士杰任海南省委书记，梁湘任省长。",impact:"建省后海南试行市场经济综合体制改革，1988年至1993年出现房地产开发投资热并一度大幅回落；2018年4月十三届全国人大一次会议批准海南全岛建设自由贸易试验区，逐步探索、稳步推进中国特色自由贸易港建设，2020年6月中共中央、国务院印发《海南自由贸易港建设总体方案》。",figures:["许士杰","梁湘"],place:"海南海口",state:"中华人民共和国",sources:["《关于设立海南省的决定》《关于建立海南经济特区的决议》（1988年4月13日第七届全国人民代表大会第一次会议通过）、《人民日报》1988年4月14日"],"tags":["海南省","经济特区","自由贸易港"]},related:["cn--1984--e01", "cn--1980--e03"]},
  {id:"cn--1988--i01",track:"cn",year:1988,yearApprox:false,dim:"institution",weight:4,title:"1988年宪法修正案通过",summary:"1988年4月12日大会通过两条宪法修正案，涉及私营经济与土地使用权。",detail:{background:"1982年宪法关于计划经济与土地不得出租的规定已与改革实践不相适应；1987年10月中央政治局原则同意把经过实践检验的成熟改革措施载入宪法，形成两条修正案草案。",process:"1988年4月12日，第七届全国人民代表大会第一次会议通过《中华人民共和国宪法修正案》第一条、第二条：第一条增加国家允许私营经济在法律规定的范围内存在和发展，明确私营经济是社会主义公有制经济的补充、国家对其实行引导、监督和管理；第二条把宪法第十条第四款修改为任何组织或者个人不得侵占、买卖、出租或者以其他形式非法转让土地，土地的使用权可以依照法律的规定转让。",impact:"这两条修正案为私营企业和国有土地有偿使用提供了宪法依据：1988年6月国务院发布《中华人民共和国私营企业暂行条例》，1990年5月发布《城镇国有土地使用权出让和转让暂行条例》；据国家工商行政管理机关的年度登记数据，到1989年底全国登记的私营企业已超过12万户。",figures:["陈丕显"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法修正案》（1988年4月12日第七届全国人民代表大会第一次会议通过）、《中华人民共和国私营企业暂行条例》（国务院1988年6月发布）"],"tags":["宪法修正案","私营经济","土地使用权转让"]},related:["cn--1987--e01", "cn--1982--i01"]},
  {id:"cn--1988--e01",track:"cn",year:1988,yearApprox:false,dim:"economy",weight:4,title:"价格改革方案公布引发抢购风",summary:"1988年放开部分商品价格前后，全国出现集中提款抢购商品现象。",detail:{background:"1988年居民对物价上涨的预期增强，前7个月物价指数已大幅上升；中央决定加快理顺价格的步伐，用两年左右时间闯过物价关。",process:"1988年7月，国务院决定放开名烟、名酒价格；8月3日至8日中央政治局在北戴河开会讨论价格、工资改革方案；1988年8月28日至30日中央政治局第十次全体会议通过的方案随后公布。方案公布前后，全国城乡出现集中提取定期存款、抢购彩电、冰箱、洗衣机以及食盐、火柴等商品的情况，居民储蓄存款的月增量一度转为负值。",impact:"据国家统计局公布的年度数据，1988年全国零售物价指数上涨18.5%，是1950年代以来较高的一年；抢购持续约两个月后随治理整顿方针的确立平息，原定两年内理顺价格的部署相应推迟，1989年至1991年价格调整明显放缓。",figures:["姚依林"],place:"北京、全国城乡",state:"中华人民共和国",sources:["《关于价格、工资改革的初步方案》（1988年8月30日中央政治局会议讨论）、国家统计局编《中国统计年鉴（1989）》（中国统计出版社1989年）"],"tags":["价格改革","抢购风潮","零售物价指数"]},related:["cn--1988--p02", "cn--1988--i01"]},
  {id:"cn--1988--p02",track:"cn",year:1988,yearApprox:false,dim:"politics",weight:3,title:"十三届三中全会确定治理整顿方针",summary:"1988年9月26日至30日全会提出治理经济环境、整顿经济秩序。",detail:{background:"1988年物价涨幅明显扩大、投资与信贷规模失控、流通领域公司过多，经济秩序的混乱问题与抢购风潮同时暴露出来。",process:"1988年9月26日至30日，中国共产党第十三届中央委员会第三次全体会议在北京举行；全会批准中央政治局确认的治理经济环境、整顿经济秩序、全面深化改革的方针，提出把今后两年改革和建设的重点放到治理经济环境、整顿经济秩序上来，压缩社会总需求、抑制通货膨胀，并原则通过了《关于价格、工资改革的初步方案》和加强纪律性有关规定。",impact:"1988年10月，国务院成立清理整顿公司领导小组，要求各级党政机关所办公司与机关在名称、财务、人事等方面脱钩；据国家统计局公布的年度数据，全社会固定资产投资增速自1989年起明显下降，物价上涨幅度到1990年回落到个位数。",figures:["赵紫阳","姚依林"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十三届中央委员会第三次全体会议公报》（1988年9月30日）、《人民日报》1988年10月1日"],"tags":["治理整顿","压缩社会总需求","清理公司"]},related:["cn--1988--e01", "cn--1987--p01"]},
  {id:"cn--1988--m01",track:"cn",year:1988,yearApprox:false,dim:"military",weight:3,title:"中国人民解放军恢复军衔制",summary:"1988年7月1日军官军衔条例通过，同年9月14日授予上将军衔。",detail:{background:"1965年5月第三届全国人大常委会决定取消军衔制度；1980年3月中央军委座谈会提出恢复军衔制的意见，1984年修订公布的《兵役法》明确中国人民解放军实行军衔制度。",process:"1988年7月1日，第七届全国人民代表大会常务委员会第二次会议通过《中国人民解放军军官军衔条例》，规定军官军衔设三等十一级，条例自公布之日起施行；1988年9月14日，中央军委在北京举行授予上将军官军衔仪式，洪学智、刘华清、秦基伟、迟浩田、杨白冰等被授予上将军衔；随后现役军官、文职干部的职务等级编制军衔与军衔标志按新制度实行。",impact:"据《中国人民解放军现役军官服役条例》的后续修订记载，1994年5月八届全国人大常委会第七次会议修改军衔条例，取消一级上将的设置并规定中央军事委员会主席不授予军衔；军衔制的恢复与1985年裁减军队员额一百万、1990年代科技练兵共同构成军队正规化建设的制度步骤。",figures:["洪学智","刘华清","迟浩田"],place:"北京",state:"中华人民共和国",sources:["《中国人民解放军军官军衔条例》（1988年7月1日第七届全国人大常委会第二次会议通过）、新华社1988年9月15日报道"],"tags":["军官军衔条例","上将授衔","军队正规化"]},related:["cn--1985--p01", "cn--1988--p02"]},
  {id:"cn--1988--e02",track:"cn",year:1988,yearApprox:false,dim:"economy",weight:3,title:"火炬计划实施与中关村试验区",summary:"1988年国家科委实施火炬计划，同年批准建立第一个国家级高新技术产业开发区。",detail:{background:"863计划自1987年起选拔课题，研究成果需要向产业转化；中关村一带高等院校与科研院所集中，民间科技企业自1980年代中期开始登记注册。",process:"1988年，国务院批准建立北京市新技术产业开发试验区，中关村成为我国第一个国家级高新技术产业开发区；同年8月，国家科委提出并开始组织实施火炬计划，以智力密集区为依托，推动863计划等研究成果的商品化与产业化，重点支持一批高技术产品开发和生产。",impact:"据国家科委公开资料，1991年3月国务院批准第一批21个国家高新技术产业开发区，此后高新区数量逐步增加；火炬计划与1985年的星火计划、1986年的863计划一起，构成这一时期我国高技术研究与成果转化的主要计划序列。",figures:["宋健"],place:"北京",state:"中华人民共和国",sources:["国家科委《关于实施火炬计划的报告》（1988年）、国务院《关于批准国家高新技术产业开发区和有关政策规定的通知》（1991年3月）"],"tags":["火炬计划","中关村","高新技术产业开发区"]},related:["cn--1986--s01", "cn--1988--i01"]},
  {id:"cn--1989--p01",track:"cn",year:1989,yearApprox:false,dim:"politics",weight:4,title:"中共十三届四中全会",summary:"1989年6月23日至24日全会选举江泽民为中央委员会总书记。",detail:{background:"据新华社公开报道，1989年春夏之交我国经历了一场政治风波；6月中旬中央政治局举行扩大会议，决定召开中央委员会全体会议并着手调整中央领导机构人事。",process:"1989年6月23日至24日，中国共产党第十三届中央委员会第四次全体会议在北京举行；全会选举江泽民为中央委员会总书记，增选江泽民、宋平、李瑞环为中央政治局常委，决定撤销赵紫阳的中央委员会总书记、中央政治局常委等职务，并组建了新的中央政治局常委和中央书记处。",impact:"这次会议后中央领导集体开始向第三代中央领导集体过渡；1989年11月6日至9日召开的十三届五中全会同意邓小平辞去中央军事委员会主席职务，决定江泽民任中央军事委员会主席，并通过《关于进一步治理整顿和深化改革的决定》（见本分片1989年条目）。",figures:["江泽民","宋平","李瑞环"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十三届中央委员会第四次全体会议公报》（1989年6月24日）、《人民日报》1989年6月25日"],"tags":["十三届四中全会","中央委员会总书记","领导机构调整"]},related:["cn--1989--p02", "cn--1987--p01"]},
  {id:"cn--1989--p02",track:"cn",year:1989,yearApprox:false,dim:"politics",weight:3,title:"邓小平辞去中央军委主席职务",summary:"1989年11月9日五中全会同意邓小平辞去中央军事委员会主席职务。",detail:{background:"邓小平多次提出退休请求，1987年十三大后不再担任中央委员，只任中央军事委员会主席；1989年9月4日他写信给中央政治局，提出完全退休的请求并推荐江泽民担任军委主席。",process:"1989年11月6日至9日，中国共产党第十三届中央委员会第五次全体会议在北京举行；全会经过讨论，同意邓小平辞去中央军事委员会主席的职务，决定江泽民任中央军事委员会主席，公报把这次主动辞职称为完善党和国家领导制度、实现中央领导集体新老交替的一个步骤。",impact:"据《邓小平文选》第三卷与新华社报道，辞任后邓小平仍以个人身份关注改革与建设问题，1992年1月至2月视察南方发表谈话，1997年2月19日在北京逝世，同年2月25日人民大会堂举行追悼大会；1982年宪法对国家领导人连续任职的规定与这一时期的交班做法，共同构成领导职务离退休制度的内容。",figures:["邓小平","江泽民","杨尚昆"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十三届中央委员会第五次全体会议公报》（1989年11月9日）、《邓小平文选》第三卷（人民出版社1993年）"],"tags":["五中全会","中央军事委员会","干部退休制度"]},related:["cn--1989--p01", "cn--1989--e01"]},
  {id:"cn--1989--p03",track:"cn",year:1989,yearApprox:false,dim:"politics",weight:4,title:"戈尔巴乔夫访华实现中苏关系正常化",summary:"1989年5月15日至18日苏联领导人访华，两国宣布关系正常化。",detail:{background:"1982年起中方提出消除中苏关系三大障碍，即苏军驻扎阿富汗、支持越南侵占柬埔寨、在中苏边境和蒙古部署大量军队；1988年至1989年越南宣布从柬埔寨撤军，障碍问题出现实质进展。",process:"1989年5月15日至18日，苏联最高苏维埃主席团主席、苏共中央总书记戈尔巴乔夫对中国进行访问，与邓小平、杨尚昆、李鹏举行会晤；邓小平在会谈中提出结束过去、开辟未来，双方会谈后发表《中苏联合公报》，宣布中苏两国关系和两党关系实现正常化，公报强调新的关系不针对第三国。",impact:"据外交部公开的交往记录，此次访问后两国经贸往来与边界谈判加快：1991年5月16日签署《中苏国界东段协定》，1991年12月27日中国承认俄罗斯联邦并建立外交关系，1996年4月上海五国元首会晤机制启动。",figures:["邓小平","戈尔巴乔夫","杨尚昆"],place:"北京",state:"中华人民共和国",sources:["《中苏联合公报》（1989年5月18日）、新华社1989年5月16日报道"],"tags":["中苏关系正常化","结束过去开辟未来","北京会晤"]},related:["cn--1989--p02", "cn--1991--p01", "world--1989--p11"]},
  {id:"cn--1989--e01",track:"cn",year:1989,yearApprox:false,dim:"economy",weight:3,title:"治理整顿和深化改革决定作出",summary:"1989年11月9日五中全会决定用三年左右时间完成治理整顿任务。",detail:{background:"1988年抢购风后中央确立治理整顿方针；1989年物价涨幅仍处于高位，同时出现市场销售疲软、国有企业资金紧张和产品销路困难并存的局面。",process:"1989年11月6日至9日，十三届五中全会通过《关于进一步治理整顿和深化改革的决定》，确定用三年或者更长的时间完成治理整顿任务，把提高经济效益作为经济工作的中心环节，具体措施包括压缩固定资产投资规模、调整投资与产业结构、清理整顿流通领域的公司和中间环节、稳定市场供应，并强调治理整顿不是否定改革方向。",impact:"据国家统计局公布的年度数据，全国零售物价上涨幅度由1989年的17.8%回落到1990年的2.1%、1991年的3.4%；同期全社会固定资产投资增速明显下降，1989年至1991年国内生产总值年均增长不足6%，市场由紧缺转为部分商品买方格局。",figures:["李鹏","姚依林"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十三届中央委员会第五次全体会议公报》（1989年11月9日）、国家统计局编《中国统计年鉴（1992）》（中国统计出版社1992年）"],"tags":["治理整顿","压缩固定资产投资","市场疲软"]},related:["cn--1988--e01", "cn--1989--p02"]},
  {id:"cn--1989--i01",track:"cn",year:1989,yearApprox:false,dim:"institution",weight:3,title:"中华人民共和国行政诉讼法通过",summary:"1989年4月4日大会通过行政诉讼法，1990年10月1日起施行。",detail:{background:"1982年公布试行的民事诉讼法曾规定法律规定的行政案件由人民法院审理；1988年起各地法院陆续设立行政审判庭试点审理不服行政处罚、行政处理的案件，但缺少统一的诉讼程序法。",process:"1989年4月4日，第七届全国人民代表大会第二次会议通过《中华人民共和国行政诉讼法》，自1990年10月1日起施行；法律规定公民、法人或者其他组织认为行政机关和行政机关工作人员的具体行政行为侵犯其合法权益，有权向人民法院提起诉讼，明确了受案范围、由被告对所作具体行政行为承担举证责任、行政诉讼不适用调解等原则。",impact:"这部法律被普遍视为我国行政诉讼制度正式确立的标志；2014年11月全国人大常委会通过修改决定，自2015年5月1日起施行新法，把立案登记、行政机关负责人出庭应诉与规范性文件附带审查写入法律，2017年又对行政公益诉讼作出补充规定。",figures:["任建新"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国行政诉讼法》（1989年4月4日第七届全国人民代表大会第二次会议通过）、《人民日报》1989年4月5日"],"tags":["行政诉讼法","民告官","举证责任"]},related:["cn--1989--p01", "cn--1991--i01"]},
  {id:"cn--1989--x01",track:"cn",year:1989,yearApprox:false,dim:"explore",weight:2,title:"中国南极中山站建成",summary:"1989年2月26日中国第二个南极考察站中山站落成。",detail:{background:"1985年2月建成的长城站位于西南极的乔治王岛，纬度较低；为开展东南极大陆冰盖与内陆科学考察，国家决定在东南极沿岸建设第二个常年考察站。",process:"1988年底至1989年2月，中国南极考察队在东南极拉斯曼丘陵施工建站；1989年2月26日，中山站举行落成典礼，站区建有固定建筑、临时舱室、码头和直升机起降平台，夏季通过海运运补建站、冬季实行越冬值守。",impact:"中山站成为我国开展东南极和内陆考察的支撑点，此后历次南极内陆冰盖考察多以沿海基地为中转；2009年1月昆仑站建成于南极内陆冰盖最高区域，2014年2月泰山站落成，中国南极考察形成多站运行的格局。",figures:["郭琨"],place:"南极洲拉斯曼丘陵",state:"中华人民共和国",sources:["新华社1989年2月27日关于中山站建成的报道、国家海洋局极地考察办公室公布的南极考察站资料"],"tags":["中山站","东南极","越冬考察"]},related:["cn--1986--x01", "cn--1985--x01"]},
  {id:"cn--1990--e01",track:"cn",year:1990,yearApprox:false,dim:"economy",weight:4,title:"中央宣布开发开放浦东",summary:"1990年4月18日国务院宣布同意上海市开发开放浦东地区。",detail:{background:"1980年代后期关于振兴上海、利用浦东土地资源的讨论持续多年；上海当时面临老市区改造资金不足、产业结构滞后的压力，中央在1990年初听取上海汇报后作出决策。",process:"1990年4月18日，国务院总理李鹏在上海宣布中共中央、国务院同意上海市加快浦东地区的开发，在浦东实行经济技术开发区和某些经济特区的政策；同年6月国务院批复上海市提出的开发开放浦东的方案，把陆家嘴、金桥、外高桥、张江等地块纳入开发范围，9月批准设立上海外高桥保税区，这是我国第一个保税区。",impact:"据上海市统计局公布的年度数据，浦东新区的地区生产总值由1990年的约60亿元增至2020年的超过1.2万亿元，以约占全市十分之一的面积贡献了全市约三分之一至四分之一的经济总量；陆家嘴金融贸易区、外高桥保税区、张江高科技园区依次建成，1990年起浦东的金融、贸易与基础设施项目开始对外招商，银行、保险与外贸机构陆续到陆家嘴设点。",figures:["李鹏","朱镕基"],place:"上海浦东",state:"中华人民共和国",sources:["新华社1990年4月19日报道、国务院《关于开发和开放浦东问题的批复》（1990年）、上海市统计局编《上海统计年鉴》"],"tags":["浦东开发开放","外高桥保税区","经济特区政策"]},related:["cn--1990--e02", "cn--1992--p01"]},
  {id:"cn--1990--e02",track:"cn",year:1990,yearApprox:false,dim:"economy",weight:4,title:"上海证券交易所正式开业",summary:"1990年12月19日上海证券交易所开业，首批上市8只股票。",detail:{background:"1984年11月上海飞乐音响公司向社会发行股票；1986年11月14日邓小平会见美国纽约证券交易所总裁时把一张飞乐音响股票赠予对方；1988年前后国务院金融体制改革的目标方案提出建立证券交易所。",process:"1990年11月26日，中国人民银行批准设立上海证券交易所并发布公告；1990年12月19日上海证券交易所正式开业，首批有34家会员席位、8只上市股票（俗称老八股），开业当日的成交金额有限，交易以口头唱报与手工交割方式开始，随后逐步过渡到电脑撮合。",impact:"据中国证监会与交易所公布的年度统计，到2000年底上海、深圳两家交易所的上市公司超过1000家，到2020年底境内上市公司超过4100家；集中交易的证券市场自此成为企业直接融资与国有企业改制的重要平台。",figures:["尉文渊","李贵鲜"],place:"上海",state:"中华人民共和国",sources:["中国人民银行《关于同意建立上海证券交易所的批复》（1990年11月）、新华社1990年12月20日报道"],"tags":["上海证券交易所","老八股","直接融资"]},related:["cn--1990--e01", "cn--1990--e03"]},
  {id:"cn--1990--e03",track:"cn",year:1990,yearApprox:false,dim:"economy",weight:2,title:"深圳证券交易所开始试营业",summary:"1990年12月1日深圳证券交易所开始试营业，1991年7月正式开业。",detail:{background:"1987年深圳发展银行成为我国首家向社会公开募股的股份制银行，1988年前后股票转让在场外进行，出现黑市交易与价格混乱，建立集中交易场所被提上日程。",process:"1990年12月1日，深圳证券交易所开始试营业；1991年4月11日经中国人民银行批准成立，1991年7月9日正式开业，最初上市的股票为5种（俗称老五股），随后陆续接纳外地企业股票挂牌。",impact:"两地交易所在1990年底至1991年相继运行；1992年10月国务院证券委员会和中国证券监督管理委员会成立，1998年12月29日《中华人民共和国证券法》通过并于1999年7月1日施行；2009年10月30日创业板首批28家公司在深交所上市，2019年7月22日科创板首批25家公司在上交所挂牌并试点注册制。",figures:["李灏"],place:"广东深圳",state:"中华人民共和国",sources:["新华社关于深圳证券交易所试营业的报道（1990年12月）、深圳证券交易所公开所史资料"],"tags":["深圳证券交易所","试营业","证券监管"]},related:["cn--1990--e02", "cn--1987--e01"]},
  {id:"cn--1990--p01",track:"cn",year:1990,yearApprox:false,dim:"politics",weight:3,title:"北京举办第十一届亚洲运动会",summary:"1990年9月22日至10月7日第11届亚运会在北京举行。",detail:{background:"1980年代北京获得第11届亚运会主办权，这是新中国第一次承办综合性国际运动会；为办赛建成国家奥林匹克体育中心、北京亚运村和改造一批场馆，资金部分来自发行亚运基金彩票与社会各界捐款。",process:"1990年9月22日至10月7日，第十一届亚洲运动会在北京举行，共有37个国家和地区的体育代表团参加，设有20多个大项、300余个小项；中国体育代表团获得183枚金牌，列金牌榜第一位，乒乓球、体操、游泳等项目有多人达到当时世界水平。",impact:"据新华社报道与后续申办记录，这届运动会之后我国开始申办奥运会；1993年9月23日在蒙特卡洛的国际奥委会投票中，北京在最后一轮以43票对45票两票之差失去2000年奥运会主办权，2001年7月13日北京获得第29届夏季奥林匹克运动会主办权。",figures:["伍绍祖","霍英东"],place:"北京",state:"中华人民共和国",sources:["第11届亚运会组委会编《北京第11届亚运会会刊》（1990年）、新华社1990年10月8日报道"],"tags":["北京亚运会","金牌榜","国家奥林匹克体育中心"]},related:["cn--1984--c01", "cn--1990--e01"]},
  {id:"cn--1990--s01",track:"cn",year:1990,yearApprox:false,dim:"science",weight:3,title:"长征三号火箭发射亚洲一号卫星",summary:"1990年4月7日中国用自研运载火箭成功发射国外商业通信卫星。",detail:{background:"1985年10月中国宣布长征系列运载火箭进入国际市场对外提供发射服务；1988年中国长城工业公司与美国休斯飞机公司签订合同，约定用长征三号火箭发射亚洲一号通信卫星。",process:"1990年4月7日，中国在西昌卫星发射中心用自行研制的长征三号运载火箭，把美国休斯公司制造的亚洲一号通信卫星准确送入地球同步转移轨道，随后卫星定点成功并按期投入运营；这是我国运载火箭第一次发射国外商业卫星。",impact:"据航天部门与新华社记载，此次发射使我国进入国际商业卫星发射服务市场，此后陆续为多个国家发射通信卫星并承揽返回式卫星搭载业务；1990年代末因国际发射市场竞争与出口管制政策调整，商业发射份额一度下降，2010年代以后长征系列火箭的年发射次数居世界前列。",figures:["任新民","王永志"],place:"四川西昌",state:"中华人民共和国",sources:["新华社1990年4月8日报道、《当代中国的航天事业》（中国社会科学出版社1992年）"],"tags":["亚洲一号","商业发射服务","长征三号"]},related:["cn--1984--s01", "cn--1987--s01"]},
  {id:"cn--1990--i01",track:"cn",year:1990,yearApprox:false,dim:"institution",weight:2,title:"中华人民共和国著作权法通过",summary:"1990年9月7日人大常委会通过著作权法，1991年6月1日施行。",detail:{background:"1986年民法通则已原则规定著作权受法律保护；1985年起国务院曾以《图书、期刊版权保护试行条例》等行政法规处理版权纠纷，作品的确权、许可与侵权责任需要正式法律。",process:"1990年9月7日，第七届全国人民代表大会常务委员会第十五次会议通过《中华人民共和国著作权法》，自1991年6月1日起施行；法律规定中国公民、法人或者非法人单位的作品不论是否发表均依照本法享有著作权，区分人身权与财产权，明确使用他人作品应当经许可并支付报酬、规定合理使用与法定许可的例外情形，并对出版者、表演者、录音录像制作者、广播电台电视台的邻接权作出规定。",impact:"据国家版权局公开资料，我国在1992年10月先后加入《伯尔尼公约》和《世界版权公约》；著作权法于2001年10月27日、2010年、2020年11月11日三次修正，最近一次自2021年6月1日起施行，增加了视听作品、惩罚性赔偿与网络环境下的保护条款。",figures:["宋木文"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国著作权法》（1990年9月7日第七届全国人大常委会第十五次会议通过）、《中华人民共和国法律汇编（1990）》（人民出版社）"],"tags":["著作权法","邻接权","合理使用"]},related:["cn--1986--i02", "cn--1990--e02"]},
  {id:"cn--1991--d01",track:"cn",year:1991,yearApprox:false,dim:"disaster",weight:3,title:"江淮流域发生特大洪涝灾害",summary:"1991年夏季江淮流域持续暴雨，安徽、江苏受灾最重。",detail:{background:"1991年入梅后，江淮流域出现大范围持续暴雨，淮河全线超警戒水位，太湖水位突破历史实测记录，部分地区内涝积水长期不退。",process:"1991年6月至7月，安徽、江苏两省灾情最重，太湖周边地区受淹，皖北与淮河流域平原排水困难；据民政部当年汇总的灾情统计，全国有18个省（区、市）遭受洪涝，受灾人口两亿余人，倒塌房屋数百万间，京沪、淮南等铁路干线一度限速或中断运行。",impact:"这年冬至1992年春，全国各地掀起兴修水利高潮，国务院作出《关于治理淮河和太湖的决定》，确立蓄泄兼筹、以泄为主并兼顾水资源利用的综合治理部署；1991年的救灾还首次较大规模接受了国际组织的援助物资，推动我国灾害救助与应急响应程序的完善。",figures:["江泽民"],place:"安徽、江苏及江淮流域18个省区市",state:"中华人民共和国",sources:["国务院《关于治理淮河和太湖的决定》（1991年）、民政部编《中国灾情报告》、新华社1991年7月关于防汛抗洪抢险的报道"],"tags":["1991年洪涝","淮河治理","兴修水利"]},related:["cn--1975--d01"]},
  {id:"cn--1991--p01",track:"cn",year:1991,yearApprox:false,dim:"politics",weight:3,title:"中越两国宣布关系正常化",summary:"1991年11月7日至10日越共领导人访华，两国宣布关系正常化。",detail:{background:"1970年代末起中越长期处于对立状态；1989年9月越南宣布从柬埔寨撤军，1991年10月23日关于柬埔寨问题的巴黎协定签署，两国关系正常化的障碍随之消除。",process:"1991年11月7日至10日，越共中央总书记杜梅、部长会议主席武文杰率团对中国进行访问，江泽民、李鹏分别会见和会谈；11月10日双方发表联合公报，宣布中越两国关系从此实现正常化，并就通过谈判解决边界问题、恢复贸易与交通往来等事项取得共识。",impact:"据外交部公开资料，两国于1992年互派大使并恢复边界谈判；1999年12月30日双方签署《中越陆地边界条约》，2000年12月25日签署《中越北部湾划界协定》和《中越北部湾渔业合作协定》，陆地边界与北部湾问题相继得到解决。",figures:["江泽民","李鹏","杜梅"],place:"北京",state:"中华人民共和国",sources:["《中越两国关系的联合公报》（1991年11月10日）、新华社1991年11月11日报道"],"tags":["中越关系正常化","杜梅访华","边界谈判"]},related:["cn--1979--m01", "cn--1989--p03"]},
  {id:"cn--1991--p02",track:"cn",year:1991,yearApprox:false,dim:"politics",weight:3,title:"中国承认俄罗斯联邦并建交",summary:"1991年12月27日中国与俄罗斯联邦确认建立外交关系。",detail:{background:"1991年12月25日戈尔巴乔夫宣布辞去苏联总统职务，次日苏联最高苏维埃宣告苏联停止存在，中国外交部表示尊重俄罗斯人民的选择并决定按新的对象处理两国关系。",process:"1991年12月27日，中华人民共和国与俄罗斯联邦以互致外长照会的方式确认继承原有中苏关系并建立大使级外交关系；同年中国还先后承认乌克兰、白俄罗斯等独立国家并与之建交，对1991年12月成立的独立国家联合体表示尊重。",impact:"据外交部公开资料，1992年12月叶利钦总统访华，双方发表联合声明确认中俄相互视为友好国家；1994年9月建立建设性伙伴关系，1996年4月上海五国机制启动并宣布建立平等信任、面向21世纪的战略协作伙伴关系，2001年7月16日签署《中俄睦邻友好合作条约》。",figures:["钱其琛"],place:"北京、莫斯科",state:"中华人民共和国",sources:["新华社1991年12月28日报道、中华人民共和国外交部《中国同俄罗斯的关系》（公开发布的国别双边关系资料）"],"tags":["中俄建交","苏联解体","外交承认"]},related:["cn--1989--p03", "cn--1996--p01", "world--1991--p06"]},
  {id:"cn--1991--i01",track:"cn",year:1991,yearApprox:false,dim:"institution",weight:2,title:"中华人民共和国民事诉讼法通过",summary:"1991年4月9日大会通过民事诉讼法，自公布之日起施行。",detail:{background:"1982年3月公布试行的民事诉讼法试行近九年；1989年行政诉讼法通过后，民事审判与商事纠纷的数量迅速增加，审判程序需要更完整的规定。",process:"1991年4月9日，第七届全国人民代表大会第四次会议通过《中华人民共和国民事诉讼法》，自公布之日起施行，同时废止1982年试行法；法律确立当事人诉讼权利平等、法院调解、公开审判与两审终审等原则，规定了起诉与受理、审判监督程序、执行程序、督促程序、公示催告程序以及涉外民事诉讼的特别规定。",impact:"据最高人民法院的立法沿革资料，民事诉讼法此后于2007年、2012年、2017年、2021年、2023年多次修正，分别完善审判监督与执行程序、增设小额诉讼与公益诉讼相关条款，并对在线诉讼与涉外程序作出规定。",figures:["任建新"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国民事诉讼法》（1991年4月9日第七届全国人民代表大会第四次会议通过）、《中华人民共和国法律汇编（1991）》（人民出版社）"],"tags":["民事诉讼法","两审终审","审判监督程序"]},related:["cn--1989--i01", "cn--1986--i02"]},
  {id:"cn--1992--p01",track:"cn",year:1992,yearApprox:false,dim:"politics",weight:5,title:"邓小平视察南方发表重要谈话",summary:"1992年1月18日至2月21日邓小平就改革与发展问题发表谈话。",detail:{background:"1991年至1992年初，理论界围绕计划与市场、改革姓社姓资的问题展开讨论，上海《解放日报》以“皇甫平”署名的系列评论文章引起广泛关注；1992年初邓小平在赴外地视察途中发表谈话。",process:"1992年1月18日至2月21日，邓小平先后视察武昌、深圳、珠海、上海等地，提出革命是解放生产力、改革也是解放生产力；判断各方面工作的是非，应主要看是否有利于发展社会主义社会的生产力、是否有利于增强社会主义国家的综合国力、是否有利于提高人民的生活水平；强调基本路线要管一百年、动摇不得，计划与市场不是社会主义与资本主义的本质区别，发展才是硬道理。",impact:"谈话内容经《人民日报》等媒体报道后在国内外引起强烈反响，当年的投资、创业与外商投资规模明显扩大；据国家统计局公布的年度数据，1992年国内生产总值比上年增长14.2%；《邓小平文选》第三卷把这次谈话的要点作为全书的末篇收入。",figures:["邓小平"],place:"湖北武昌、广东深圳与珠海、上海",state:"中华人民共和国",sources:["《邓小平文选》第三卷（人民出版社1993年）、《中国共产党第十四届中央委员会第一次全体会议公报》（1992年10月19日）"],"tags":["南方谈话","三个有利于","发展才是硬道理"]},related:["cn--1992--p02", "cn--1987--p01"]},
  {id:"cn--1992--p02",track:"cn",year:1992,yearApprox:false,dim:"politics",weight:5,title:"中共十四大确立市场经济体制目标",summary:"1992年10月12日至18日大会提出建立社会主义市场经济体制。",detail:{background:"1992年6月9日江泽民在中央党校省部级干部进修班上就经济体制改革目标发表讲话，提出建立社会主义的市场经济体制；6月底中央政治局会议讨论后取得一致意见，为大会作准备。",process:"1992年10月12日至18日，中国共产党第十四次全国代表大会在北京举行，江泽民作《加快改革开放和现代化建设步伐，夺取有中国特色社会主义事业的更大胜利》的报告；大会明确经济体制改革的目标是建立社会主义市场经济体制，使市场在国家宏观调控下对资源配置起基础性作用，用中国特色社会主义理论武装全党，并决定不再设立中央顾问委员会。",impact:"据十四届一中全会公报，江泽民当选中央委员会总书记和中央军事委员会主席；1993年3月宪法修正案把国家实行社会主义市场经济写入根本法；据国家统计局数据，1992年至1997年国内生产总值年均增长超过11%，价格闯关式的调整转为整体性制度变革。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《加快改革开放和现代化建设步伐，夺取有中国特色社会主义事业的更大胜利》（1992年10月12日，人民出版社1992年）、《中国共产党第十四次全国代表大会文件汇编》（人民出版社1992年）"],"tags":["中共十四大","社会主义市场经济","基础性作用"]},related:["cn--1992--p01", "cn--1993--i01"]},
  {id:"cn--1992--p03",track:"cn",year:1992,yearApprox:false,dim:"politics",weight:3,title:"中国与韩国建立外交关系",summary:"1992年8月24日两国签署建交联合公报，互派大使。",detail:{background:"1983年5月中国民航一架客机被劫持飞到汉城，中方人员就此与韩方进行了第一次官方接触；1986年9月中国体育代表团参加在汉城举行的第10届亚洲运动会，两国的经贸与人员往来在1980年代后期明显增加，韩国与台湾当局的外交关系在这一过程中被重新评估。",process:"1992年8月24日，中华人民共和国外交部长钱其琛与韩国外务部长官李相玉在北京签署《中华人民共和国与大韩民国关于建立外交关系的联合公报》，两国自公报之日起互相承认并建立大使级外交关系；公报中韩国方面表示尊重中华人民共和国关于只有一个中国的立场，并注意台湾方面的特殊关系。",impact:"据外交部公开资料与海关统计，建交后两国经贸关系快速上升，1992年双边贸易额约50亿美元，此后中国连续多年成为韩国最大的贸易伙伴之一；1992年9月两国互设使馆并陆续签订民航、海上通航与投资保护协定。",figures:["钱其琛","李相玉"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国与大韩民国关于建立外交关系的联合公报》（1992年8月24日）、新华社1992年8月25日报道"],"tags":["中韩建交","联合公报","东北亚外交"]},related:["cn--1992--p01", "cn--1991--p02"]},
  {id:"cn--1992--i01",track:"cn",year:1992,yearApprox:false,dim:"institution",weight:3,title:"企业转换经营机制条例发布",summary:"1992年6月30日国务院发布条例，赋予国有企业14项经营自主权。",detail:{background:"1988年4月13日七届全国人大一次会议通过《全民所有制工业企业法》，自1988年8月1日施行，但企业反映厂长负责制的职权仍受行政部门的审批与摊派限制。",process:"1992年6月30日，国务院发布《全民所有制工业企业转换经营机制条例》，规定企业享有生产经营决策、产品及劳务定价、产品销售、物资采购、进出口、投资决策、留用资金支配、资产处置、联营兼并、劳动用工、人事管理、工资奖金分配、内部机构设置以及拒绝摊派等14项权利，同时规定企业对国有资产承担保值增值与自负盈亏的责任。",impact:"据国家经济体制改革委员会的公开资料，条例发布后各地集中开展落实企业自主权的检查；1993年11月十四届三中全会通过《中共中央关于建立社会主义市场经济体制若干问题的决定》，把改革方向推进到以产权清晰、权责明确、政企分开、管理科学为特征的现代企业制度。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《全民所有制工业企业转换经营机制条例》（1992年6月30日国务院发布）、《中华人民共和国法规汇编（1992）》"],"tags":["转换经营机制","企业经营自主权","国有企业"]},related:["cn--1992--p02", "cn--1988--i01"]},
  {id:"cn--1992--s01",track:"cn",year:1992,yearApprox:false,dim:"science",weight:4,title:"中国载人航天工程批准实施",summary:"1992年9月21日中央批准实施载人航天工程并确定三步走方案。",detail:{background:"1986年863计划把航天技术列为重点领域的专题之一；1987年起国家科委组织航天领域专家完成载人航天工程的可行性论证，形成以载人飞船起步、分步发展的方案建议。",process:"1992年9月21日，中央政治局常务委员会批准实施中国载人航天工程，确定三步走发展战略：第一步发射载人飞船，建成初步配套的试验性载人飞船工程并开展空间应用实验；第二步突破航天员出舱活动、载人飞船与空间实验室交会对接技术，发射空间实验室；第三步建造空间站，解决有较大规模的、长期有人照料的空间应用问题；工程设立系统总体设计部，王永志任总设计师。",impact:"据中国载人航天工程办公室公开资料，2003年10月神舟五号实现首次载人飞行，2008年神舟七号完成首次出舱活动，2021年4月29日天和核心舱发射、2022年底空间站全面建成并转入应用与发展阶段。",figures:["王永志"],place:"北京",state:"中华人民共和国",sources:["中国载人航天工程办公室公开发布的工程发展历程资料、《当代中国的航天事业》（中国社会科学出版社1992年）"],"tags":["载人航天工程","三步走","空间实验室"]},related:["cn--1986--s01"]},
  {id:"cn--1992--m01",track:"cn",year:1992,yearApprox:false,dim:"military",weight:3,title:"中国首次派出成建制维和部队",summary:"1992年4月中国军事工程大队和护士分队赴柬埔寨参加维和。",detail:{background:"1990年4月中国首次派出军事观察员参加联合国驻中东的停战监督组织；1991年10月联合国安理会通过设立联合国柬埔寨过渡时期权力机构的决议，授权在柬埔寨实施过渡期维和。",process:"1992年3月至4月，中国组成军事工程大队和护士分队开赴柬埔寨，参加联合国柬埔寨过渡时期权力机构的维持和平行动，这是我国第一次派出成建制的军事工程部队参与联合国维和；工程大队在柬埔寨修复公路、桥梁并执行排雷任务。",impact:"据2020年9月发布的《中国军队参加联合国维和行动30年》白皮书，我国此后先后在莫桑比克、东帝汶、利比里亚、刚果（金）、南苏丹等地执行维和任务，30年累计派出维和人员4万余人次，是安理会常任理事国中派出维和人员最多的国家。",figures:["钱其琛"],place:"柬埔寨",state:"中华人民共和国",sources:["新华社1992年4月关于中国维和部队赴柬埔寨的报道、《中国军队参加联合国维和行动30年》白皮书（国务院新闻办公室2020年9月）"],"tags":["联合国维和","军事工程大队","柬埔寨"]},related:["cn--1992--p01"]},
  {id:"cn--1992--e01",track:"cn",year:1992,yearApprox:false,dim:"economy",weight:3,title:"1992年经济增速达百分之十四点二",summary:"国家统计局核定1992年国内生产总值比上年增长14.2%。",detail:{background:"南方谈话与十四大之后，各地出现兴办开发区、扩大基建投资的热潮，房地产与交通、通信投资同步升温，企业人员停薪留职经商、技术人员下海的数量增加。",process:"据国家统计局公布的年度数据，1992年国内生产总值比上年增长14.2%，全年全社会固定资产投资比上年增长44.4%，实际使用外商直接投资约110亿美元，比上年增加近一倍；同年全国各级各类开发区数量急剧扩张，部分地区出现违规占用耕地设立开发区的情况。",impact:"高增长同时带来投资与信贷双膨胀、金融秩序混乱和物价上涨压力，1993年6月中央发出《关于当前经济情况和加强宏观调控的意见》提出16条措施（见1993年条目）；据国家土地管理部门的公开资料，1993年至1994年各地按国务院部署撤销、合并了过多过滥的开发区。",figures:["邹家华"],place:"北京、全国",state:"中华人民共和国",sources:["国家统计局编《中国统计年鉴（1993）》（中国统计出版社1993年）、《1992年国民经济和社会发展的统计公报》（国家统计局1993年2月发布）"],"tags":["1992年经济增长","外商直接投资","开发区热"]},related:["cn--1992--p01", "cn--1993--e01"]},
  {id:"cn--1993--p01",track:"cn",year:1993,yearApprox:false,dim:"politics",weight:3,title:"八届全国人大一次会议组成国家机构",summary:"1993年3月15日至31日会议选举江泽民为国家主席，决定李鹏任总理。",detail:{background:"1993年3月全国政协八届一次会议先行召开；本次全国人大会议的主要议程是审议宪法修正案、国务院机构改革方案、选举和决定新一届国家机构领导人员。",process:"1993年3月15日至31日，第八届全国人民代表大会第一次会议在北京举行；会议于3月27日选举江泽民为中华人民共和国主席，同时决定由他任中央军事委员会主席，3月28日根据国家主席的提名决定李鹏为国务院总理，会议还通过国务院机构改革方案，决定把综合经济部门改组为宏观调控部门，撤销一批专业经济管理部门。",impact:"本届会议把国家实行社会主义市场经济等内容写入宪法修正案；据公开资料，改革后国务院组成部门由1988年的86个调整为59个，专业工业部门的管理职能开始向行业协会与企业转移，为1998年更大幅度的机构改革作了准备。",figures:["江泽民","李鹏","乔石"],place:"北京",state:"中华人民共和国",sources:["第八届全国人民代表大会第一次会议新闻公报（1993年3月31日）、《人民日报》1993年3月28日"],"tags":["八届全国人大一次会议","国务院机构改革","国家主席"]},related:["cn--1993--i01", "cn--1992--p02"]},
  {id:"cn--1993--i01",track:"cn",year:1993,yearApprox:false,dim:"institution",weight:4,title:"1993年宪法修正案通过",summary:"1993年3月29日大会通过宪法修正案，把社会主义市场经济载入根本法。",detail:{background:"1992年10月中共十四大已确立经济体制改革的目标是建立社会主义市场经济体制；1992年12月中央政治局研究提出修改宪法的建议，八届全国人大一次会议主席团将修正案草案提请大会审议。",process:"1993年3月29日，第八届全国人民代表大会第一次会议通过共9条宪法修正案：在序言中增写我国正处于社会主义初级阶段、建设有中国特色社会主义的理论和坚持改革开放，增写中国共产党领导的多党合作和政治协商制度将长期存在和发展；把国家在社会主义公有制基础上实行计划经济修改为国家实行社会主义市场经济；把国营经济、国营企业的表述改为国有经济、国有企业；规定国有企业有权自主经营；把县级人民代表大会每届任期由3年改为5年。",impact:"修正案使宪法与十四大确定的改革目标相衔接；此后全国人大又于1999年3月15日、2004年3月14日、2018年3月11日通过宪法修正案，分别把邓小平理论、三个代表重要思想、人权保障、私有财产保护与监察委员会等写入宪法。",figures:["乔石"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法修正案》（1993年3月29日第八届全国人民代表大会第一次会议通过）、新华社1993年3月30日报道"],"tags":["宪法修正案","社会主义市场经济","任期五年"]},related:["cn--1992--p02", "cn--1988--i01"]},
  {id:"cn--1993--p02",track:"cn",year:1993,yearApprox:false,dim:"politics",weight:4,title:"十四届三中全会勾画市场经济体制框架",summary:"1993年11月11日至14日全会通过建立社会主义市场经济体制的决定。",detail:{background:"十四大提出改革目标后，需要回答怎样建立的问题；1993年上半年中央组织起草组在调查研究的基础上形成决定草稿，并征求了地方和中央有关部门的意见。",process:"1993年11月11日至14日，中国共产党第十四届中央委员会第三次全体会议在北京举行，通过《中共中央关于建立社会主义市场经济体制若干问题的决定》，把改革目标具体化为相互联结的几大环节：建立产权清晰、权责明确、政企分开、管理科学的现代企业制度，培育和发展市场体系，健全宏观调控体系，改革收入分配制度与社会保障制度；决定明确公有制的主体地位主要体现在公有资产在社会总资产中占优势。",impact:"据国务院公布的改革时序，1994年起分税制财政体制、汇率并轨、三家政策性银行分立与现代企业制度试点等措施相继出台；这个决定被视为1990年代中期经济体制改革的行动纲领，其框架在2003年十六届三中全会关于完善社会主义市场经济体制的决定中得到延续。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于建立社会主义市场经济体制若干问题的决定》（1993年11月14日通过）、《十四大以来重要文献选编》（上，人民出版社1995年）"],"tags":["十四届三中全会","现代企业制度","宏观调控体系"]},related:["cn--1992--p02", "cn--1994--e01"]},
  {id:"cn--1993--e01",track:"cn",year:1993,yearApprox:false,dim:"economy",weight:4,title:"中央提出加强宏观调控十六条",summary:"1993年6月24日中央发出意见，提出加强宏观调控的16条措施。",detail:{background:"1992年下半年至1993年上半年，投资与信贷双膨胀、违章拆借资金、乱设金融机构与房地产开发区过热同时出现，1993年上半年商品零售价格涨幅接近20%。",process:"1993年6月24日，中共中央、国务院印发《关于当前经济情况和加强宏观调控的意见》（中发〔1993〕6号），提出16条措施，包括严格控制货币发行、坚决纠正违章拆借资金、取缔非法金融机构、提高存贷款利率、清理压缩固定资产投资在建与上新项目、强化中央银行对金融体系的监管；同年7月2日八届全国人大常委会第二次会议决定由国务院副总理朱镕基兼任中国人民银行行长。",impact:"据国家统计局公布的年度数据，1993年国内生产总值增长14.0%、1994年增长13.1%，商品零售价格涨幅在1994年达到21.7%的峰值后逐年回落，1996年回落到6.1%；整顿金融秩序与后来的分税制、汇率并轨共同构成这一轮宏观调控的制度内容。",figures:["朱镕基"],place:"北京",state:"中华人民共和国",sources:["中共中央、国务院《关于当前经济情况和加强宏观调控的意见》（中发〔1993〕6号，1993年6月24日）、国家统计局编《中国统计年鉴（1996）》（中国统计出版社1996年）"],"tags":["加强宏观调控","整顿金融秩序","抑制通货膨胀"]},related:["cn--1992--e01", "cn--1994--e01"]},
  {id:"cn--1993--e02",track:"cn",year:1993,yearApprox:false,dim:"economy",weight:3,title:"粮票在全国范围停止使用",summary:"1993年各地陆续中止使用粮票，城镇粮食定量供应制度结束。",detail:{background:"1955年9月起全国实行市镇粮食定量供应与粮票制度；1985年取消粮食统购、改为合同定购后，多地先后提高粮食销售价格并减少财政补贴，1991年至1992年又有大批城市放开口粮价格。",process:"1993年，国务院发出加快粮食流通体制改革的通知，要求在本届政府任期内基本放开粮食价格和经营；随后各省、自治区、直辖市陆续中止使用粮票、油票等购粮凭证，延续近四十年的城镇粮食定量供应制度结束，同时要求县级以上政府建立粮食风险基金和地方粮食储备。",impact:"据国家粮食储备部门与国家统计局的公开资料，票证退出后城镇居民的口粮消费转由市场供应；1990年代后期出现主产区卖粮难与粮价持续走低，1998年起实行按保护价敞开收购农民余粮的政策，2004年起改为对重点品种实行最低收购价并叠加种粮直接补贴。",figures:["朱镕基"],place:"北京、全国城乡",state:"中华人民共和国",sources:["《国务院关于加快粮食流通体制改革的通知》（1993年）、国家统计局编《中国统计年鉴（1994）》（中国统计出版社1994年）"],"tags":["粮票","粮食流通体制","粮食风险基金"]},related:["cn--1985--e01", "cn--1993--e01"]},
  {id:"cn--1993--s01",track:"cn",year:1993,yearApprox:false,dim:"science",weight:3,title:"银河二号十亿次巨型机研制成功",summary:"1993年10月17日银河—Ⅱ并行巨型计算机通过国家鉴定。",detail:{background:"1983年12月银河—Ⅰ亿次巨型计算机通过国家鉴定；此后气象预报、石油勘探与科学计算对每秒十亿次以上并行处理能力的需要促使新一轮研制立项。",process:"1993年10月17日，国防科学技术大学研制的银河—Ⅱ并行巨型计算机在长沙通过国家鉴定，实际运算速度达到每秒10亿次，是我国第一台每秒十亿次量级的并行巨型机；整机采用自主设计的并行体系结构，配有并行操作系统、编译系统与并行应用工具。",impact:"据科技部与学校公开的沿革资料，此后我国高性能计算机走向多条技术路线并行：1990年代后期曙光系列并行机实现产业化，2002年神威系列问世，2010年天河一号在国际超级计算机组织公布的年度排名中列第一位，国家高性能计算中心相继在多地布局。",figures:["慈云桂"],place:"湖南长沙",state:"中华人民共和国",sources:["新华社1993年10月关于银河—Ⅱ巨型计算机通过鉴定的报道、国家科学技术部编《中国科技统计年鉴》"],"tags":["银河二号","并行巨型机","高性能计算"]},related:["cn--1983--s01", "cn--1987--s01"]},
  {id:"cn--1993--c01",track:"cn",year:1993,yearApprox:false,dim:"culture",weight:2,title:"毛泽东诞辰一百周年纪念大会",summary:"1993年12月26日中央在人民大会堂举行毛泽东百年诞辰纪念大会。",detail:{background:"1981年十一届六中全会的历史决议已对毛泽东晚年的错误作出分析；1993年是毛泽东诞生100周年，中央决定举行纪念大会并同步出版其建国后的文稿与年谱。",process:"1993年12月26日，毛泽东同志诞辰100周年纪念大会在北京人民大会堂举行，江泽民发表讲话，强调要坚持和发展马克思列宁主义、毛泽东思想，学习毛泽东等老一辈革命家的崇高风范；同一时期中央档案馆编辑的《毛泽东文集》建国后部分三卷本与修订本的《毛泽东年谱》由人民出版社、中央文献研究室陆续公开出版。",impact:"据中央文献研究部门的公开出版记录，这批文稿与年谱为1949年以后时段的研究提供了新的一手材料；2003年12月26日中央举行毛泽东同志诞辰110周年座谈会，纪念方式由大会改为座谈会。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《在毛泽东同志诞辰一百周年纪念大会上的讲话》（1993年12月26日）、新华社1993年12月27日"],"tags":["毛泽东诞辰百年","纪念大会","文献出版"]},related:["cn--1981--p01", "cn--1993--p01"]},
  {id:"cn--1994--e01",track:"cn",year:1994,yearApprox:false,dim:"economy",weight:4,title:"分税制财政管理体制开始实行",summary:"国务院1993年12月25日作出决定，分税制自1994年1月1日起实施。",detail:{background:"1980年代起实行的财政包干体制造成中央财政收入占全国财政收入的比重不断下降，到1993年降到22%左右，中央财政连年向地方借款；1993年11月十四届三中全会把分税制确定为财税改革方向。",process:"1993年12月25日，国务院发布《关于实行分税制财政管理体制的决定》，自1994年1月1日起实施：按税种划分中央税、地方税与中央地方共享税，消费税归中央，增值税由中央分享75%、地方分享25%，同时把国有企业按行政隶属关系上缴利润的办法改为统一税制，1994年起组建国家税务与地方税务两套征收机构，并建立对地方的税收返还和转移支付制度。",impact:"据财政部与国家统计局公布的年度数据，中央财政收入占全国财政收入的比重由1993年的22%提高到1994年的55.7%，此后长期保持在50%以上，全国财政收入由1993年的5114亿元增加到1999年的11444亿元；县乡财政困难与地方政府对土地出让收入的依赖也成为此后持续讨论的问题，2016年国务院印发《关于推进中央与地方财政事权和支出责任划分改革的指导意见》。",figures:["刘仲藜"],place:"北京",state:"中华人民共和国",sources:["国务院《关于实行分税制财政管理体制的决定》（1993年12月25日发布）、财政部编《中国财政年鉴（1995）》（中国财政经济出版社1995年）"],"tags":["分税制","增值税分享","转移支付"]},related:["cn--1993--p02", "cn--1993--e01"]},
  {id:"cn--1994--e02",track:"cn",year:1994,yearApprox:false,dim:"economy",weight:3,title:"人民币汇率实行官方与调剂市场并轨",summary:"1994年1月1日人民币两种汇率并轨为1美元兑8.70元。",detail:{background:"1981年起人民币长期实行官方汇率与外汇调剂市场汇率并存的双重汇率制度；1993年底官方汇率为1美元兑5.80元，而调剂市场汇率已达8.7元左右，出口企业须通过调剂市场换汇。",process:"1994年1月1日，人民币官方汇率与外汇调剂市场汇率并轨为1美元兑8.70元，开始实行以市场供求为基础的、单一的、有管理的浮动汇率制度；企业外汇上缴改为银行结汇、售汇制度，1994年4月中国外汇交易中心在上海成立并开始运行，同年6月全国统一的银行间外汇市场联网运行。",impact:"并轨后出口与外汇储备明显增长：据国家统计局与外汇管理部门公布的数据，1994年全年出口总额1210亿美元、比上年增长31.9%，国家外汇储备由1993年底的212亿美元增加到1994年底的516亿美元；1996年12月1日我国接受国际货币基金组织协定第八条款，实现人民币经常项目下可兑换。",figures:["朱镕基"],place:"北京、上海",state:"中华人民共和国",sources:["国务院《关于进一步改革外汇管理体制的通知》（1993年12月28日）、国家统计局编《中国统计年鉴（1995）》（中国统计出版社1995年）"],"tags":["汇率并轨","结售汇","经常项目可兑换"]},related:["cn--1994--e01", "cn--1993--e01"]},
  {id:"cn--1994--e03",track:"cn",year:1994,yearApprox:false,dim:"economy",weight:3,title:"长江三峡工程正式开工",summary:"1994年12月14日三峡水利枢纽工程在宜昌三斗坪正式开工。",detail:{background:"关于长江三峡水利枢纽的论证历时数十年；1992年4月3日第七届全国人民代表大会第五次会议作出《关于兴建长江三峡工程的决议》，这是全国人大首次对一个工程项目表决。",process:"1994年12月14日，长江三峡水利枢纽工程在湖北省宜昌市三斗坪正式开工；拦河大坝坝顶高程185米，水库正常蓄水位175米，电站装机总容量2250万千瓦；工程分三期建设，1997年11月8日实现大江截流，2003年6月水库初期蓄水至135米、首批机组发电、双线五级船闸通航。",impact:"据国务院三峡工程建设委员会办公室与水利部的公开资料，2006年5月大坝全线浇筑到坝顶高程，2020年11月完成整体竣工验收；工程以防洪为首要任务，兼有发电、航运与水资源调度功能，库区累计搬迁安置移民约130万人。",figures:["邹家华"],place:"湖北宜昌三斗坪",state:"中华人民共和国",sources:["《关于兴建长江三峡工程的决议》（1992年4月3日第七届全国人民代表大会第五次会议通过）、新华社1994年12月15日报道"],"tags":["三峡工程","大江截流","库区移民"]},related:["cn--1997--p03", "cn--1994--e01"]},
  {id:"cn--1994--i01",track:"cn",year:1994,yearApprox:false,dim:"institution",weight:3,title:"中华人民共和国劳动法通过",summary:"1994年7月5日人大常委会通过劳动法，1995年1月1日起施行。",detail:{background:"1986年国务院发布国营企业实行劳动合同制等四个暂行规定，推行劳动合同制；1992年后各类所有制企业用工形式多样化，劳动争议的处理缺少统一法律。",process:"1994年7月5日，第八届全国人民代表大会常务委员会第八次会议通过《中华人民共和国劳动法》，自1995年1月1日起施行；法律适用于境内的企业、个体经济组织及其劳动者，规定用人单位应当与劳动者订立书面劳动合同，国家实行劳动者每日工作时间不超过8小时、平均每周工作时间不超过44小时的工时制度，确立最低工资保障、劳动安全卫生、女职工和未成年工特殊保护、社会保险与福利以及劳动争议处理程序。",impact:"与劳动法相配套，全国人大常委会于2007年6月29日通过《中华人民共和国劳动合同法》，自2008年1月1日施行、2012年12月28日修订；1995年3月25日国务院修改《职工工作时间的规定》，自1995年5月1日起职工每周工作40小时，即通行的双休日制度。",figures:["李鹏"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国劳动法》（1994年7月5日第八届全国人民代表大会常务委员会第八次会议通过）、国务院《关于修改职工工作时间的规定的决定》（1995年3月25日）"],"tags":["劳动法","劳动合同","最低工资"]},related:["cn--1994--i02", "cn--1996--i01"]},
  {id:"cn--1994--i02",track:"cn",year:1994,yearApprox:false,dim:"institution",weight:3,title:"中华人民共和国国家赔偿法通过",summary:"1994年5月12日人大常委会通过国家赔偿法，1995年1月1日施行。",detail:{background:"1982年宪法规定因国家机关和国家工作人员侵犯公民权利而受到损失的人有取得赔偿的权利；1989年行政诉讼法规定了行政侵权赔偿责任，但赔偿范围、标准与程序需要专门立法。",process:"1994年5月12日，第八届全国人民代表大会常务委员会第七次会议通过《中华人民共和国国家赔偿法》，自1995年1月1日起施行；法律把国家赔偿分为行政赔偿与刑事赔偿两类，规定行政机关及其工作人员违法行使职权侵犯人身权、财产权时的赔偿方式与计算标准，明确对没有犯罪事实或者没有事实证明有犯罪重大嫌疑的人错误拘留、错误逮捕以及再审改判无罪等情形给予赔偿，并规定赔偿费用列入各级财政预算。",impact:"据最高人民法院与最高人民检察院公布的司法解释沿革，国家赔偿法于2010年4月29日修改、自2010年12月1日施行，取消了赔偿前的违法确认程序并增加精神损害抚慰金；侵犯人身自由每天的赔偿金按国家上年度职工日平均工资计算，自2012年起逐年调整公布。",figures:["乔石"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国国家赔偿法》（1994年5月12日第八届全国人民代表大会常务委员会第七次会议通过）、《中华人民共和国法律汇编（1994）》（人民出版社）"],"tags":["国家赔偿","刑事赔偿","精神损害抚慰金"]},related:["cn--1989--i01", "cn--1996--i01"]},
  {id:"cn--1994--s01",track:"cn",year:1994,yearApprox:false,dim:"science",weight:5,title:"中国实现与国际互联网全功能连接",summary:"1994年4月20日我国通过国际专线实现全功能接入国际互联网。",detail:{background:"1987年我国研究者向国际网络发出第一封电子邮件；1989年起国家自然科学基金委员会主持建设中关村地区网络连接试验工程，1993年该网络通过卫星信道与国外网络互通，当时只能使用电子邮件等有限功能。",process:"1994年4月20日，中关村地区网络连接试验工程通过一条64K的国际专线实现与国际互联网的全功能连接，我国由此可以使用互联网的全部功能开展网络应用；同年中国科学院和高等学校的网络陆续接入，1995年1月由邮电部门承建的公用计算机互联网开始建设并于1996年2月正式开通。",impact:"据中国互联网络信息中心发布的历次《中国互联网络发展状况统计报告》，我国网民规模在2001年12月为3370万人，2018年底超过8.2亿、互联网普及率接近60%，截至2023年12月网民规模超过10.9亿、普及率超过77%；电子商务、网络支付与平台经济在此后成为就业与消费的重要渠道。",figures:["钱天白"],place:"北京",state:"中华人民共和国",sources:["中国科学院公开的中关村地区网络连接试验工程资料、中国互联网络信息中心《中国互联网络发展状况统计报告》"],"tags":["国际互联网","全功能接入","中关村地区网络"]},related:["cn--1986--s01", "cn--1994--e02"]},
  {id:"cn--1994--p01",track:"cn",year:1994,yearApprox:false,dim:"politics",weight:3,title:"中央召开第三次西藏工作座谈会",summary:"1994年7月20日至23日座谈会作出发展西藏与全国支援西藏的部署。",detail:{background:"中央于1980年3月、1984年先后召开第一次、第二次西藏工作座谈会；1980年代末90年代初西藏基础设施与产业发展滞后，1989年7月中央政治局常委会议听取汇报后提出了西藏工作的指导方针。",process:"1994年7月20日至23日，中共中央、国务院在北京召开第三次西藏工作座谈会，围绕加快西藏经济社会发展与维护社会稳定作出部署，确定由中央国家机关和内地省份对口支援西藏、分期建设一批经济社会发展急需的项目，并明确中央给予西藏的优惠政策在长期内不变。",impact:"据国务院新闻办公室《西藏和平解放与繁荣发展》白皮书（2021年5月）与西藏自治区统计局公布的年度数据，对口援藏机制此后延续至多批干部与项目投入，西藏地区生产总值由1990年代的数十亿元增加到2020年的1902.64亿元，2006年7月青藏铁路全线通车改变了西藏不通铁路的历史。",figures:["江泽民","李鹏"],place:"北京",state:"中华人民共和国",sources:["新华社1994年7月关于第三次西藏工作座谈会的报道、国务院新闻办公室《西藏和平解放与繁荣发展》白皮书（2021年5月）"],"tags":["第三次西藏工作座谈会","对口援藏","边疆发展"]},related:["cn--2006--e01"]},
  {id:"cn--1995--s01",track:"cn",year:1995,yearApprox:false,dim:"science",weight:4,title:"科教兴国战略首次明确提出",summary:"1995年5月6日中共中央、国务院决定实施科教兴国战略。",detail:{background:"1978年3月全国科学大会提出科学技术是生产力；1986年863计划、1988年火炬计划与星火计划相继实施；1993年7月《中华人民共和国科学技术进步法》施行后，需要确定新阶段的总体战略。",process:"1995年5月6日，中共中央、国务院公布《关于加速科学技术进步的决定》，首次以中央文件的形式明确提出实施科教兴国战略，要求把经济建设转移到依靠科技进步和提高劳动者素质的轨道上来，建立面向经济建设、服务社会发展的科技体制，逐步提高全社会研究与开发经费占国内生产总值的比例，并决定设立支持基础研究的天文、数学等若干国家重点实验室体系与青年科学基金。",impact:"据国家统计局与科技部公布的《全国科技经费投入统计公报》，全国研究与试验发展经费由1995年的349亿元增加到2020年的24426亿元、2023年超过3.3万亿元，投入强度由0.56%提高到2.5%以上；1998年3月中国科学院启动知识创新工程试点，2016年5月全国科技创新大会提出建设世界科技强国的目标。",figures:["李鹏","宋健"],place:"北京",state:"中华人民共和国",sources:["中共中央、国务院《关于加速科学技术进步的决定》（1995年5月6日）、国家统计局与科技部历年《全国科技经费投入统计公报》"],"tags":["科教兴国","科技进步","研发投入强度"]},related:["cn--1986--s01", "cn--1995--i01"]},
  {id:"cn--1995--e01",track:"cn",year:1995,yearApprox:false,dim:"economy",weight:3,title:"十四届五中全会提出两个根本性转变",summary:"1995年9月25日至28日全会通过制定九五计划和2010年远景目标的建议。",detail:{background:"1995年国内生产总值比1980年翻两番的目标提前实现，中央着手研究今后15年的发展战略；当时经济增长主要依靠要素投入扩张，资源与环境约束开始显现。",process:"1995年9月25日至28日，中国共产党第十四届中央委员会第五次全体会议在北京举行，通过《中共中央关于制定国民经济和社会发展“九五”计划和2010年远景目标的建议》，提出实现经济体制从传统的计划经济体制向社会主义市场经济体制转变、经济增长方式从粗放型向集约型转变这两个具有全局意义的根本性转变，并确定今后15年国民生产总值年均增长8%左右、2000年人均国民生产总值比1980年翻两番的目标。",impact:"据国家统计局公布的年度数据，1996年至2000年国内生产总值年均增长8.3%，2000年人均国内生产总值比1980年翻两番的第二步目标完成，全国总体上达到小康水平；建议提出的经济增长方式转变在此后历次五年计划文件中延续，2007年十七大进一步改为加快转变经济发展方式。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《中共中央关于制定国民经济和社会发展“九五”计划和2010年远景目标的建议》（1995年9月28日通过）、国家统计局编《中国统计年鉴（2001）》（中国统计出版社2001年）"],"tags":["九五计划","两个根本性转变","经济增长方式"]},related:["cn--1995--s01", "cn--1996--e01"]},
  {id:"cn--1995--p01",track:"cn",year:1995,yearApprox:false,dim:"politics",weight:2,title:"江泽民提出发展两岸关系八项主张",summary:"1995年1月30日新春茶话会提出推进祖国和平统一进程的八项主张。",detail:{background:"1993年4月27日至29日，海协会会长汪道涵与海基会董事长辜振甫在新加坡举行汪辜会谈，两岸授权团体的制度性接触开始；1995年前后两岸关系因台湾方面的活动趋于紧张。",process:"1995年1月30日，中共中央总书记、国家主席江泽民在北京举行新春茶话会上发表《为促进祖国统一大业的完成而继续奋斗》的讲话，就发展两岸关系、推进祖国和平统一进程提出八项主张，包括坚持一个中国原则是实现和平统一的基础和前提、对于台湾同外国发展民间关系不持异议、双方举行谈判可以实现两岸三通与双向交流、欢迎台湾同胞回到家乡探亲、共同弘扬中华文化的优秀传统等。",impact:"据国务院台湾事务办公室公开资料，八项主张与1992年达成的九二共识一起成为此后大陆方面对台政策的基本框架；1995年6月至1996年两岸关系因台湾领导人访美与军事演习一度紧张（见本分片1996年条目），2005年3月十届全国人大三次会议通过《反分裂国家法》。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《为促进祖国统一大业的完成而继续奋斗》（1995年1月30日，收入《江泽民文选》第一卷，人民出版社2006年）、新华社1995年1月31日"],"tags":["八项主张","两岸关系","和平统一"]},related:["cn--1979--p02", "cn--1996--m01"]},
  {id:"cn--1995--p02",track:"cn",year:1995,yearApprox:false,dim:"politics",weight:3,title:"第四次世界妇女大会在北京举行",summary:"1995年9月4日至15日大会通过北京宣言和行动纲要。",detail:{background:"联合国先后于1980年在哥本哈根、1985在内罗毕召开第二次、第三次世界妇女大会；1993年联合国大会接受中国的承办邀请，1995年2月国务院颁布《中国妇女发展纲要（1995—2000年）》作准备。",process:"1995年9月4日至15日，第四次世界妇女大会在北京举行，来自189个国家和地区的代表以及联合国机构、非政府组织的观察员与会，江泽民在开幕式上讲话；大会通过《北京宣言》和《行动纲要》，提出在12个关键领域促进性别平等的战略目标，大会期间还在北京怀柔同期举行了非政府组织论坛。",impact:"据国务院新闻办公室《中国性别平等与妇女发展》白皮书（2015年9月）与历次《中国妇女发展纲要》统计监测报告，北京大会之后妇女发展指标被纳入国家规划体系，2012年与2021年分别颁布新的两期妇女发展纲要；2015年全国女性就业人员占全社会就业人员的比重为45%左右。",figures:["江泽民","彭珮云"],place:"北京",state:"中华人民共和国",sources:["第四次世界妇女大会《北京宣言》和《行动纲要》（1995年9月）、新华社1995年9月15日报道"],"tags":["第四次世界妇女大会","北京宣言","行动纲要"]},related:["cn--1995--i01", "cn--1995--p01"]},
  {id:"cn--1995--i01",track:"cn",year:1995,yearApprox:false,dim:"institution",weight:2,title:"中华人民共和国教育法通过",summary:"1995年3月18日大会通过教育法，自1995年9月1日起施行。",detail:{background:"1986年义务教育法与1985年教育体制改革决定、1993年《中国教育改革和发展纲要》已分别就普及义务教育和体制作出部署，教育领域需要一部综合性的基本法律。",process:"1995年3月18日，第八届全国人民代表大会第三次会议通过《中华人民共和国教育法》，自1995年9月1日起施行；法律确立国家实行学前教育、初等教育、中等教育、高等教育的学校教育制度与九年制义务教育制度，规定职业教育、成人教育与国家教育考试制度，明确学校及其他教育机构的设立条件、教师资格与职务制度，规定教育经费以各级人民政府财政拨款为主并逐步提高财政性教育经费占国内生产总值的比例，同时规定国家实行教育与宗教相分离。",impact:"据教育部公布的历年全国教育事业发展统计公报，国家财政性教育经费占国内生产总值的比例在2012年首次达到4%，此后连续保持在4%以上；教育法于2015年12月27日、2021年4月29日两次修正，进一步明确了教育公平与义务教育免试就近入学的要求。",figures:["朱开轩"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国教育法》（1995年3月18日第八届全国人民代表大会第三次会议通过）、教育部编《中国教育年鉴（1995）》（人民教育出版社1995年）"],"tags":["教育法","财政性教育经费","教育与宗教分离"]},related:["cn--1986--i01", "cn--1995--s01"]},
  {id:"cn--1996--p01",track:"cn",year:1996,yearApprox:false,dim:"politics",weight:4,title:"上海五国元首会晤机制启动",summary:"1996年4月24日至26日五国元首在上海会晤并签署边境信任协定。",detail:{background:"1991年中俄关系重建后边界谈判加快；1990年代中期中国与俄罗斯及三个新独立的中亚邻国就边境地区的军事信任与裁军进行多轮会谈，四国领导人于1996年4月应邀访华。",process:"1996年4月24日至26日，江泽民与俄罗斯总统叶利钦、哈萨克斯坦总统纳扎尔巴耶夫、吉尔吉斯斯坦总统阿卡耶夫、塔吉克斯坦总统拉赫莫诺夫在上海举行会晤，26日五国签署《关于在边境地区加强军事领域信任的协定》，规定相互通报边境地区军事活动、不在边境地区使用武力、允许有限度的军事视察与军事接触；这次会晤由此形成上海五国元首年度会晤机制。",impact:"据外交部公开资料，1997年4月24日五国在莫斯科签署《关于在边境地区裁减军事力量的条约》；2001年6月15日六国在上海宣布成立上海合作组织，2024年7月白俄罗斯加入后成员国增至九个，该组织每年举行元首会晤并开展联合反恐军事演习。",figures:["江泽民","叶利钦","纳扎尔巴耶夫"],place:"上海",state:"中华人民共和国",sources:["《关于在边境地区加强军事领域信任的协定》（1996年4月26日签署于上海）、新华社1996年4月27日报道"],"tags":["上海五国","边境军事信任","上海合作组织"]},related:["cn--1991--p02"]},
  {id:"cn--1996--i01",track:"cn",year:1996,yearApprox:false,dim:"institution",weight:3,title:"中华人民共和国行政处罚法通过",summary:"1996年3月17日大会通过行政处罚法，自1996年10月1日起施行。",detail:{background:"1989年行政诉讼法实施后，行政机关设定与实施处罚的权限缺乏统一规范，实践中存在乱设罚款、罚没收入与部门利益挂钩等问题。",process:"1996年3月17日，第八届全国人民代表大会第四次会议通过《中华人民共和国行政处罚法》，自1996年10月1日起施行；法律确立处罚法定与公正公开原则，规定行政处罚只能由法律、法规和规章依照法定权限设定，限制人身自由的处罚只能由法律设定，实行罚款决定与罚款收缴分离，并规定简易程序、一般程序与听证程序，行政机关作出责令停产停业、吊销许可证或者执照、较大数额罚款等决定前应当告知当事人有要求举行听证的权利。",impact:"该法与1989年行政诉讼法、1994年国家赔偿法、1999年行政复议法共同构成规范行政权力的法律框架；2021年1月22日修订后的行政处罚法增加首违可以不罚、没有法律依据或不遵守法定程序的处罚无效等规定，并对电子技术监控设备取证作出规范。",figures:["乔石"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国行政处罚法》（1996年3月17日第八届全国人民代表大会第四次会议通过）、《中华人民共和国法律汇编（1996）》（人民出版社）"],"tags":["行政处罚","听证程序","罚缴分离"]},related:["cn--1989--i01", "cn--1994--i02"]},
  {id:"cn--1996--e01",track:"cn",year:1996,yearApprox:false,dim:"economy",weight:3,title:"宏观调控使经济运行实现软着陆",summary:"据国家统计局数据，1996年国内生产总值增长10.0%、零售物价涨6.1%。",detail:{background:"1993年加强宏观调控与1994年财税、金融、外贸等改革相继出台后，中央实行适度从紧的财政政策和货币政策，遏制通货膨胀被确定为1994年至1996年经济工作的首要任务。",process:"据国家统计局公布的年度数据，全国商品零售价格上涨幅度由1994年的21.7%回落到1995年的17.1%、1996年的6.1%，同期国内生产总值仍保持较快增长，1996年增长10.0%；固定资产投资增速明显下降，1996年12月1日我国实现人民币经常项目下可兑换，年底国家外汇储备超过1000亿美元。",impact:"官方与学界把这轮在保持较高增长的同时把物价涨幅压回个位数、又未出现经济负增长的过程称为软着陆；据国家统计局数据，1997年国内生产总值增长9.2%、商品零售价格涨幅回落到0.8%，长期困扰我国的高通胀问题在这一阶段得到控制。",figures:["朱镕基"],place:"北京",state:"中华人民共和国",sources:["国家统计局编《中国统计年鉴（1997）》（中国统计出版社1997年）、中国人民银行1996年12月关于人民币经常项目可兑换的公告"],"tags":["软着陆","抑制通货膨胀","适度从紧的财政货币政策"]},related:["cn--1993--e01", "cn--1994--e02"]},
  {id:"cn--1996--m01",track:"cn",year:1996,yearApprox:false,dim:"military",weight:3,title:"解放军在台湾海峡附近举行军事演习",summary:"1995年下半年至1996年3月，解放军在东南沿海组织演习与导弹试验。",detail:{background:"1995年6月台湾地区领导人李登辉到美国活动，中国政府提出抗议并召回驻美大使进行磋商；1996年是台湾地区第一次领导人直接选举的年份，中央多次重申台湾问题属于中国内政。",process:"据新华社与《人民日报》公开报道，1995年7月、10月与1996年3月，中国人民解放军先后在东海、台湾海峡附近海域组织导弹实弹试验、海空军演习和陆海空三军联合渡海登陆演习，1996年3月的演习与导弹试射安排在台湾地区领导人选举前后；美国于1996年3月派出两个航空母舰战斗群到台湾以东海域，是1950年代以来美军在西太平洋较大规模的舰队调动。",impact:"据新华社报道与国防部公开资料，这一轮军事演习与外交交涉之后，中央继续以八项主张与九二共识作为对台政策的基础框架，1997年至1999年两会接触与谈判筹备几度中断；2005年3月十届全国人大三次会议通过《反分裂国家法》，规定在和平统一的可能性完全丧失的情况下国家得采取非和平方式及其他必要措施。",figures:["张万年"],place:"福建沿海与台湾海峡海域",state:"中华人民共和国",sources:["新华社、《人民日报》1995年至1996年关于军事演习与导弹试射的报道、国务院台湾事务办公室《台湾问题与中国统一》白皮书（1993年8月）"],"tags":["台海军事演习","导弹试射","两岸关系"]},related:["cn--1995--p01"]},
  {id:"cn--1997--p01",track:"cn",year:1997,yearApprox:false,dim:"politics",weight:5,title:"中国政府对香港恢复行使主权",summary:"1997年7月1日中英政权交接，香港特别行政区政府成立。",detail:{background:"1982年9月至1984年12月中英两国经过两轮、共22次会谈解决香港问题，1984年12月19日正式签署联合声明并于1985年5月27日互换批准书；1990年4月4日七届全国人大三次会议通过《中华人民共和国香港特别行政区基本法》，1996年12月董建华当选第一任行政长官。",process:"1997年6月30日午夜至7月1日凌晨，中英两国政府在香港会议展览中心举行政权交接仪式，江泽民宣告中国政府1997年7月1日零时对香港恢复行使主权；末任港督彭定康于6月30日傍晚在港督府降下英国国旗，7月1日香港特别行政区政府成立，董建华就任第一任行政长官，基本法开始施行，香港保持原有资本主义制度五十年不变、实行港人治港与高度自治。",impact:"据新华社与中央政府公布的资料，1998年亚洲金融危机期间香港金融市场上遭遇投机冲击，特区政府在中央政府支持下入市干预并维持了联系汇率制度；2003年6月29日签署《内地与香港关于建立更紧密经贸关系的安排》、同年7月启动内地居民个人赴港旅游，2020年5月28日全国人大通过建立健全香港维护国家安全的法律制度和执行机制的决定，同年6月30日《香港特别行政区维护国家安全法》公布施行。",figures:["江泽民","董建华","彭定康"],place:"香港",state:"中华人民共和国",sources:["《中华人民共和国政府和联合王国政府关于香港问题的联合声明》（1984年12月19日签署）、新华社1997年7月1日报道"],"tags":["香港回归","一国两制","基本法"]},related:["cn--1984--p01", "cn--1997--p02"]},
  {id:"cn--1997--p02",track:"cn",year:1997,yearApprox:false,dim:"politics",weight:4,title:"中共十五大把邓小平理论写入党章",summary:"1997年9月12日至18日大会确立邓小平理论为党的指导思想。",detail:{background:"1997年2月19日邓小平在北京逝世，2月25日人民大会堂举行追悼大会，江泽民在悼词中论述其历史地位；大会的主题由此围绕高举邓小平理论旗帜展开。",process:"1997年9月12日至18日，中国共产党第十五次全国代表大会在北京举行，江泽民作《高举邓小平理论伟大旗帜，把建设有中国特色社会主义事业全面推向二十一世纪》的报告；大会把邓小平理论同马克思列宁主义、毛泽东思想一起确立为党的指导思想并写入党章，提出党在社会主义初级阶段的基本纲领，明确公有制为主体、多种所有制经济共同发展是我国社会主义初级阶段的一项基本经济制度，把依法治国确立为党领导人民治理国家的基本方略，并提出到2010年形成中国特色社会主义法律体系。",impact:"据十五届一中全会公报，江泽民继续当选中央委员会总书记；十五大后国有企业改革与脱困三年目标、1998年国务院机构改革与住房制度改革相继推进；2002年11月十六大把三个代表重要思想写入党章，2007、2012、2017、2022年历次大会延续了五年一次的制度节奏。",figures:["江泽民"],place:"北京",state:"中华人民共和国",sources:["《高举邓小平理论伟大旗帜，把建设有中国特色社会主义事业全面推向二十一世纪》（1997年9月12日，人民出版社1997年）、《中国共产党第十五次全国代表大会文件汇编》（人民出版社1997年）"],"tags":["中共十五大","邓小平理论","依法治国"]},related:["cn--1997--p01", "cn--1992--p02"]},
  {id:"cn--1997--p03",track:"cn",year:1997,yearApprox:false,dim:"politics",weight:3,title:"全国人大批准设立重庆直辖市",summary:"1997年3月14日大会批准设立重庆直辖市，同年6月18日挂牌。",detail:{background:"1996年9月中央决定把四川省的重庆市及万县、涪陵、黔江等地合并设立直辖市，主要考虑是三峡库区移民的集中安置与长江上游老工业基地的带动；1997年2月八届全国人大常委会第二十四次会议审议了该议案。",process:"1997年3月14日，第八届全国人民代表大会第五次会议通过《关于批准设立重庆直辖市的决定》，批准设立重庆直辖市，管辖原重庆市、万县市、涪陵市和黔江地区，面积8.24万平方公里；1997年6月18日重庆直辖市挂牌成立，张德江任市委书记，蒲海清任市长。",impact:"据重庆市统计局公布的年度数据，重庆地区生产总值由1997年的1638亿元增加到2023年的30145.79亿元，经济总量进入全国城市前四；直辖市体制与1992年设立的国家级重庆经济技术开发区、2010年6月上海浦东之后的第三个国家级开发开放平台两江新区一起，构成三峡后续发展问题的制度安排。",figures:["张德江","蒲海清"],place:"重庆",state:"中华人民共和国",sources:["《关于批准设立重庆直辖市的决定》（1997年3月14日第八届全国人民代表大会第五次会议通过）、新华社1997年6月19日报道"],"tags":["重庆直辖市","三峡库区移民","行政区划"]},related:["cn--1994--e03", "cn--1997--p01"]},
  {id:"cn--1997--i01",track:"cn",year:1997,yearApprox:false,dim:"institution",weight:4,title:"修订后的中华人民共和国刑法通过",summary:"1997年3月14日大会通过修订刑法，同年10月1日起施行。",detail:{background:"1979年刑法是我国第一部刑法；此后立法机关制定了大量单行刑事法律与补充规定，罪名与刑罚需要统一编纂，实践中类推制度的弊端也受到批评。",process:"1997年3月14日，第八届全国人民代表大会第五次会议修订通过《中华人民共和国刑法》，自1997年10月1日起施行；修订后的刑法把反革命罪修改为危害国家安全罪，确立罪刑法定、适用刑法人人平等与罪责刑相适应三项原则，取消了1979年刑法中的类推制度，把原来的流氓罪、投机倒把罪、玩忽职守罪分解为若干具体罪名，并规定了单位犯罪与累犯、自首、立功、缓刑、假释等制度。",impact:"据全国人大公布的立法资料，到2023年12月全国人大常委会已通过十二个刑法修正案；2015年8月29日刑法修正案（九）取消9个罪名的死刑并增设终身监禁，2020年12月26日刑法修正案（十一）就低龄未成年人恶性犯罪、高空抛物、冒名顶替等作出规定，2023年12月29日刑法修正案（十二）加大对民营企业内部腐败行为的惩治。",figures:["乔石","顾昂然"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国刑法》（1997年3月14日第八届全国人民代表大会第五次会议修订通过）、新华社1997年3月15日报道"],"tags":["刑法修订","罪刑法定","取消类推"]},related:["cn--1979--i01", "cn--1996--i01"]},
  {id:"cn--1997--e01",track:"cn",year:1997,yearApprox:false,dim:"economy",weight:4,title:"亚洲金融危机与人民币不贬值承诺",summary:"1997年7月起东南亚发生金融危机，中国宣布人民币不贬值。",detail:{background:"1997年7月2日泰国放弃固定汇率制、泰铢改为浮动汇率，金融动荡随即波及菲律宾、马来西亚、印度尼西亚，1997年11月韩国亦陷入外债危机并接受国际货币基金组织的救助安排。",process:"1997年12月起，中国政府公开宣布保持人民币汇率稳定、不实行竞争性贬值的承诺，同时提高部分商品的出口退税率、加强资本项目管制并开展打击走私与骗汇的专项行动；据中国人民银行与财政部公开资料，中国还通过国际货币基金组织等多边渠道向受冲击的经济体提供资金支持，并于1997年12月与东盟国家开始就区域金融合作展开磋商。",impact:"据国际货币基金组织《世界经济展望》（1998年）与国家统计局公布的数据，1997年至1999年受冲击经济体的货币贬值幅度较大而人民币汇率保持稳定，这被视为亚洲地区稳定预期的关键之举；国内则因出口受阻与1998年洪灾影响，1998年起转而实施积极的财政政策与稳健的货币政策，把扩大内需作为基本立足点（见1998年条目）。",figures:["朱镕基"],place:"北京",state:"中华人民共和国",sources:["新华社1997年12月关于人民币汇率稳定的报道、国际货币基金组织《世界经济展望》（1998年）、国家统计局编《中国统计年鉴（1999）》（中国统计出版社1999年）"],"tags":["亚洲金融危机","人民币不贬值","扩大内需"]},related:["cn--1996--e01", "cn--1998--e03", "world--1997--e01"]},
  {id:"cn--1997--a01",track:"cn",year:1997,yearApprox:false,dim:"art",weight:2,title:"电影《甲方乙方》开创内地贺岁片",summary:"1997年冯小刚执导的《甲方乙方》公映，被视为内地第一部贺岁片。",detail:{background:"1994年起我国以分账方式引进海外影片，而国产电影的观众人次自1970年代末的高峰持续下滑，1990年代中期全国电影票房不足10亿元，岁末档期的影院缺少国产影片支撑。",process:"1997年，冯小刚执导、葛优等主演的喜剧片《甲方乙方》由北京电影制片厂与紫禁城影业公司联合出品，以面向节日档期的宣发方式在寒假与春节期间于北京首轮放映，取得数百万元票房；业内与媒体由此把这类面向岁末档期、以京味喜剧和小品式段落结构为特征的国产影片称为贺岁片，冯小刚此后连续推出《不见不散》《没完没了》等同类影片。",impact:"据国家电影局公布的年度数据，全国电影票房由2002年的不足10亿元增长到2019年的642.7亿元，2020年因疫情下降到203亿元，2023年为549.2亿元；贺岁档此后与暑期档一起成为国产影片最重要的两个档期，2023年春节档票房超过67亿元。",figures:["冯小刚","葛优"],place:"北京",state:"中华人民共和国",sources:["《中国电影年鉴（1998）》（中国电影出版社1998年）、国家电影局公布的年度电影票房统计数据"],"tags":["贺岁片","甲方乙方","电影档期"]},related:["cn--1994--s01"]},
];
